// Extrae las etiquetas [x] … [fin_x] del Documento Maestro
const texto = $input.first().json.content || '';
const { tipo, linea, fase } = $('Datos de Monday').first().json;
const v = {};
const re = /\[([^\]\n]+)\]([\s\S]*?)\[fin_\1\]/g;
let m;
while ((m = re.exec(texto)) !== null) v[m[1].trim()] = m[2].trim();


// Docentes: solo los que vienen llenos.
// Sesión Magistral: se leen dentro de [equipo_docente] … [fin_equipo_docente] (en el resto del documento
// [docente_1] también aparece con la biografía). Seminarios y cursos siguen leyendo [docente_1] … como siempre
let fuente = v;
if (tipo === 'sesion') {
  fuente = {};
  const r = new RegExp(re.source, 'g');
  while ((m = r.exec(v.equipo_docente || '')) !== null) fuente[m[1].trim()] = m[2].trim();
}
let docentes = [1, 2, 3, 4, 5].map(n => (fuente['docente_' + n] || '').trim()).filter(Boolean);
// Especialización: el docente de las piezas es el director del programa ([director] del Documento Maestro)
if (tipo === 'especializacion' || tipo === 'diplomado') docentes = [(v.director || v.director_programa || '').trim()].filter(Boolean);
// Diplomado: institución adicional (aún sin diseño automático → aviso para agregarla a mano)
const instExtra = (v.institucion_adicional1 || '').trim();
const institucion_extra = !!instExtra && !/^\(?\s*no\s+aplica\s*\)?$|^[-–—.]*$/i.test(instExtra) ? instExtra : '';
// Precios ("$ 590.000" → 590000)
const num = s => parseInt(String(s || '').replace(/[^\d]/g, ''), 10) || 0;
const precio_pre = num(v['precio_pre-lanzamiento'] || v.precio_prelanzamiento), precio_normal = num(v.precio_normal);

// Revisión rápida de datos (según el tipo de programa)
const faltan = [];
if (!v.nombre_programa) faltan.push('nombre_programa');
if (tipo === 'curso') {
  if (linea !== 'CA' && !/^\d{4}-\d{2}-\d{2}/.test(v.fecha_inicio || '')) faltan.push('fecha_inicio (formato AAAA-MM-DD HH:MM)');
  if (!/^\d+$/.test((v.horas_certificadas || '').trim())) faltan.push('horas_certificadas (solo el número)');
} else if (tipo === 'seminario') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v.fecha || '')) faltan.push('fecha (formato AAAA-MM-DD)');
  if (!/^\d{1,2}:\d{2}$/.test(v.horario || '')) faltan.push('horario (formato HH:MM)');
}
// Acreditación: solo el primer docente (foto y nombre en la pieza)
if (tipo === 'acreditacion') docentes = docentes.slice(0, 1);
// Diplomado y Acreditación: fecha_inicio con mes y año
if ((tipo === 'diplomado' || tipo === 'acreditacion') && !/(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)[\s\S]*\b20\d{2}\b|\d{4}-\d{2}-\d{2}/i.test(v.fecha_inicio || '')) faltan.push('fecha_inicio (con mes y año, ej. "Viernes 05 de marzo de 2027")');
// Especialización, Diplomado y Acreditación: horas certificadas y, en prelanzamiento, los precios para calcular el % de descuento
if (['especializacion', 'diplomado', 'acreditacion'].includes(tipo)) {
  if (!/^\d+$/.test((v.horas_certificadas || '').trim())) faltan.push('horas_certificadas (solo el número)');
  if (fase === 'pre' && !(precio_pre && precio_normal && precio_pre < precio_normal)) faltan.push('precio_pre-lanzamiento y precio_normal (para calcular el % de descuento)');
}
// Sesión Magistral: no lleva fecha ni horario
if (!docentes.length) faltan.push(tipo === 'sesion' ? 'al menos un docente en [equipo_docente] ([docente_1] …)' : tipo === 'especializacion' ? 'director en el Documento Maestro ([director])' : tipo === 'diplomado' ? 'director en el Documento Maestro ([director_programa])' : 'al menos un docente');

return [{ json: {
  nombre_programa: v.nombre_programa || '',
  fecha: v.fecha || '',
  horario: v.horario || '',
  fecha_inicio: v.fecha_inicio || '',
  horas_certificadas: (v.horas_certificadas || '').trim(),
  docentes,
  faltan,
  etiquetas_encontradas: Object.keys(v).length,
  // Versión 2: fuente de "¿Qué aprenderás?"
  objetivos_especificos: (v.objetivos_especificos || '').trim(),
  objetivo_general: (v.objetivo_general || '').trim(),
  ...(tipo === 'especializacion' ? { precio_pre, precio_normal } : {}),
  ...(tipo === 'diplomado' ? { precio_pre, precio_normal, institucion_extra } : {}),
} }];

// Fotos de docentes: las elegidas en "Elegir foto SF" (carpeta del docente → Otras fotos → _SF_V<n>)
const fotos = $('Elegir foto SF').first().json.fotos || [];

// Doodle (viene del nodo anterior) → base64, para el nodo Armar HTML piezas
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = $input.first().binary.data.mimeType || 'image/png';
const doodle = `data:${mime};base64,${buf.toString('base64')}`;

// Un ítem por docente: el nodo siguiente descarga cada foto
return fotos.map((f, i) => ({ json: {
  n: f.n,
  nombre: f.nombre,
  file_id: f.file_id,
  ...(i === 0 ? { doodle, faltan: [] } : {}),
} }));

// Revisa que esté todo antes de generar las piezas. Si falta algo, arma el texto para la columna Error de Monday
const dm = $('Datos de Monday').first().json;
const ex = $('Extraer etiquetas').first().json;
// Imagen representativa. Diplomado: la búsqueda de Drive trae también 1080X1920-POPUP (coincide la palabra "POPUP"),
// así que se elige la que se llama exactamente 1920X1080-POPUP. El resto de las líneas: la primera, como siempre
const doodle = dm.tipo === 'diplomado'
  ? ($('Buscar doodle').all().map(i => i.json).find(x => /^1920X1080-POPUP\./i.test((x.name || '').trim())) || {})
  : $('Buscar doodle').first().json;
const fotos = $('Elegir foto SF').first().json;

const faltan = [...(dm.faltan || []), ...(ex.faltan || [])];
const norm = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

if (dm.tipo === 'seminario') {
  // Países: solo los configurados; con varios países, el Documento Maestro debe traer prefijo (CL/MX/CO/AR)
  const CONFIGURADOS = ['chile', 'colombia', 'mexico', 'argentina'];
  const desconocidos = (dm.paises || []).filter(p => !CONFIGURADOS.includes(norm(p)));
  if (desconocidos.length) faltan.push('país sin configurar: ' + desconocidos.join(', '));
  if ((dm.paises || []).length > 1 && !dm.pais_doc) faltan.push('prefijo de país en el nombre del Documento Maestro (CL/MX/CO/AR)');
}

if (dm.tipo === 'curso' || dm.tipo === 'especializacion') {
  // Escuela(s) del curso o especialización: columna "Escuela" del programa; máximo 2 y reconocidas
  const CODIGOS = { 'salud mental adultos': 'SMA', 'salud mental infantojuvenil': 'SMIJ', 'psicologia organizacional': 'PO', 'psicosocial juridica': 'PSJ', 'educacion y neurodesarrollo': 'EN' };
  const escs = fotos.escuelas || [];
  if (!escs.length) faltan.push('Escuela del curso (columna "Escuela" del programa en Monday)');
  const raras = escs.filter(e => !Object.keys(CODIGOS).some(k => norm(e).includes(k)));
  if (raras.length) faltan.push('Escuela sin logo configurado: ' + raras.join(', '));
  if (escs.length > 2) faltan.push('más de 2 Escuelas: hacer la pieza manual');
}

// Docentes: máximo 2 por pieza. Sesión Magistral no tiene límite: con más de 3, las piezas salen sin nombres
// ("Elegir foto SF") y diseño los agrega a mano
const maxDoc = 2;
if (!['sesion', 'diplomado'].includes(dm.tipo) && (ex.docentes || []).length > maxDoc) faltan.push(`más de ${maxDoc} docentes: hacer la pieza manual`);

// Sesión Magistral: foto del tema (FONDO.png) en "Gráficas programa"
let fondo_id = '', carpeta_pais_id = '';
if (dm.tipo === 'sesion') {
  let archivos = [];
  try { archivos = $('Buscar fondo').first().json.files || []; } catch (e) {}
  const f = archivos.find(x => /^fondo\.(png|jpe?g|webp)$/i.test((x.name || '').trim())) || archivos[0];
  if (f) fondo_id = f.id;
  else faltan.push('imagen "FONDO.png" en la carpeta Gráficas programa');
  // Carpeta del país (CL / MX / CO) dentro de la carpeta del programa: ahí se suben las RRSS
  let carpetas = [];
  try { carpetas = $('Buscar carpeta país').first().json.files || []; } catch (e) {}
  if (carpetas[0]) carpeta_pais_id = carpetas[0].id;
  else faltan.push(`carpeta "${dm.pais_sm}" en la carpeta del programa (al lado de Gráficas programa)`);
}

// Acreditación: foto del tema (FONDO.png) en "Gráficas programa"
if (dm.tipo === 'acreditacion') {
  let archivos = [];
  try { archivos = $('Buscar fondo').first().json.files || []; } catch (e) {}
  const f = archivos.find(x => /^fondo\.(png|jpe?g|webp)$/i.test((x.name || '').trim())) || archivos.find(x => /fondo/i.test(x.name || ''));
  if (f) fondo_id = f.id;
  else faltan.push('imagen "FONDO.png" en la carpeta Gráficas programa');
}

// Diplomado: ilustración vertical opcional (1080X1920-POPUP); si no está, se usa la horizontal en todas las piezas
let popup_v_id = '';
if (dm.tipo === 'diplomado') {
  let archivos = [];
  try { archivos = $('Buscar fondo').first().json.files || []; } catch (e) {}
  const v = archivos.find(x => /1080X1920-POPUP/i.test(x.name || ''));
  if (v) popup_v_id = v.id;
}

// Versión 2: todas las líneas (Seminario, Cursos CS y CA, Diplomado/Postítulo, Especialización, Acreditación y Sesión Magistral); necesita [objetivos_especificos] (CA: [objetivo_general]) para "¿Qué aprenderás?"
if (dm.v2) {
  // Los cursos se separan por línea: curso_CS (Sincrónico) / curso_CA (Asincrónico)
  const V2_LISTAS = ['seminario', 'curso_CS', 'curso_CA', 'diplomado', 'especializacion', 'acreditacion', 'sesion'];
  const claveV2 = dm.tipo === 'curso' ? 'curso_' + dm.linea : dm.tipo;
  if (!V2_LISTAS.includes(claveV2)) faltan.push(`versión 2 aún no disponible para esta línea (${claveV2 || 'sin tipo'})`);
  if (claveV2 === 'curso_CA') { if (!ex.objetivo_general) faltan.push('objetivo_general en el Documento Maestro (para "¿Qué aprenderás?")'); }
  else if (!ex.objetivos_especificos) faltan.push('objetivos_especificos en el Documento Maestro (para "¿Qué aprenderás?")');
}

// Fotos: carpeta del docente → "Otras fotos" → archivo _SF_V<n>
faltan.push(...(fotos.faltan || []));

// Imagen representativa en "Gráficas programa" (doodle de seminario o ilustración POPUP de curso)
if (!doodle.id) faltan.push(`imagen "${dm.tipo === 'diplomado' ? '1920X1080-POPUP' : ['sesion', 'especializacion', 'acreditacion'].includes(dm.tipo) ? '1200X1200-POPUP' : '1200X1200-PopUp'}" en la carpeta Gráficas programa`);

const ok = faltan.length === 0;
const fecha = new Intl.DateTimeFormat('es-CL', { timeZone: 'America/Santiago', day: '2-digit', month: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date());

return [{ json: {
  ok,
  error: ok ? '' : `${fecha} · Falta: ${faltan.join('; ')}`,
  id: doodle.id || '',   // lo usa "Descargar doodle"
  ...(dm.tipo === 'sesion' ? { fondo_id, carpeta_pais_id } : {}),
  ...(dm.tipo === 'diplomado' ? { popup_v_id } : {}),
  ...(dm.tipo === 'acreditacion' ? { fondo_id } : {}),   // lo usa "Insumos acreditación"   // lo usa "Insumos diplomado"   // lo usa "Descargar fondo" (Sesión Magistral)
} }];

// Revisa que todos los archivos quedaron en Drive (cada subida devuelve un id de archivo)
const piezas = $('Formatos de salida').all().map(i => i.json.nombre_archivo);
const subidas = $input.all().map(i => i.json);
const faltan = piezas.filter((nombre, i) => !(subidas[i] && subidas[i].id));
const ok = piezas.length > 0 && faltan.length === 0;
const fecha = new Intl.DateTimeFormat('es-CL', { timeZone: 'America/Santiago', day: '2-digit', month: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date());

return [{ json: {
  ok,
  subidas: subidas.filter(j => j.id).length,
  error: ok ? '' : `${fecha} · No se subieron a Drive: ${faltan.join(', ') || 'piezas incompletas'}`,
} }];

// Docentes del programa: Tablero Subida → Docente/s → Carpeta Docente (link_mm12j260)
// También trae la Escuela del programa (cursos), el nombre del docente según su país (catálogo)
// y el país del docente (bandera en Sesión Magistral) y su "Pronombre(s)" (Director / Directora / Dirección en Diplomado y Especialización)
const r = $input.first().json;
if (r.errors) throw new Error('Monday: ' + JSON.stringify(r.errors));
const subida = ((((r.data || {}).items || [])[0] || {}).column_values) || [];
const norm = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const docentes = [];
let escuelas = [];
for (const cv of subida)
  for (const ts of (cv.linked_items || []))
    for (const dcv of (ts.column_values || [])) {
      if (norm((dcv.column || {}).title) === 'escuela' && dcv.text)
        escuelas = dcv.text.split(',').map(x => x.trim()).filter(Boolean);
      for (const d of (dcv.linked_items || [])) {
        const c = id => (d.column_values || []).find(x => x.id === id) || {};
        let url = '';
        try { url = JSON.parse(c('link_mm12j260').value || '{}').url || ''; } catch (e) {}
        if (!url) url = ((c('link_mm12j260').text || '').match(/https?:\/\/\S+/) || [])[0] || '';
        const carpeta_id = (url.match(/folders\/([^\/?#]+)/) || [])[1] || '';
        // Catálogo: nombre según el país del docente (MX / CO); Chile u otro país → nombre CL (el del ítem)
        const pais = norm(c('men__desplegable7').text);
        const nombre_catalogo = (pais === 'mexico' && c('texto15').text) || (pais === 'colombia' && c('text_mkpjbgnj').text) || d.name;
        // "Pronombre(s)" (Él / Ella / Elle) del tablero Información Docentes (columna men__desplegable58)
        const pronombre = c('men__desplegable58').text || ((d.column_values || []).find(x => norm((x.column || {}).title).startsWith('pronombre')) || {}).text || '';
        if (!docentes.find(x => x.docente_id === d.id)) docentes.push({ docente_id: d.id, nombre_monday: d.name, nombre_catalogo, carpeta_id, pais: (c('men__desplegable7').text || '').trim(), pronombre: pronombre.trim() });
      }
    }
// Siempre sale al menos un ítem, para que el flujo llegue a "Validar datos" y avise
const lista = docentes.length ? docentes : [{ docente_id: '', nombre_monday: '', nombre_catalogo: '', carpeta_id: '', pais: '', pronombre: '' }];
return lista.map(j => ({ json: { ...j, escuelas } }));

// Elige la foto sin fondo (_SF_V<n>, la versión más alta) de cada docente del Documento Maestro
// (en Sesión Magistral, en cambio, toma el país de cada docente para su bandera)
const carpetas = $('Docentes y carpetas').all().map(i => i.json);
const otras = $('Buscar Otras fotos').all().map(i => i.json);
const listas = $input.all().map(i => i.json);
const delDoc = $('Extraer etiquetas').first().json.docentes || [];

// Compara nombres sin títulos ("PhD.", "Mg.", "Flga.") ni tildes
const norm = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const nucleo = s => norm(s).split(/\s+/).filter(t => t && !t.endsWith('.')).map(t => t.replace(/[^a-zñ]/g, '')).filter(Boolean);
const calza = (a, b) => {
  const A = nucleo(a), B = nucleo(b);
  if (!A.length || !B.length) return false;
  const [corto, largo] = A.length <= B.length ? [A, B] : [B, A];
  return corto.every(t => largo.includes(t));
};

const monday = carpetas.map((c, i) => ({
  ...c,
  otras: ((otras[i] || {}).files || [])[0],
  archivos: (listas[i] || {}).files || [],
}));

const faltan = [];
const fotos = [];
const tipo = $('Datos de Monday').first().json.tipo;

// Sesión Magistral: no usa foto _SF_ (las fotos vienen en el 1200X1200-POPUP). Solo el país de cada docente → bandera.
// Países configurados (banderas provisorias de flagcdn.com). Un país nuevo se agrega aquí; si no está, el ítem queda en Datos incompletos.
const BANDERAS = {
  'estados unidos': 'us', 'eeuu': 'us', 'ee.uu.': 'us', 'usa': 'us',
  'chile': 'cl', 'argentina': 'ar', 'mexico': 'mx', 'colombia': 'co',
  'inglaterra': 'gb-eng',
};
const docentes_sm = [];
if (tipo === 'sesion') {
  // Más de 3 docentes: las piezas salen sin nombres ni banderas (diseño los agrega a mano)
  if (delDoc.length > 3) return [{ json: { fotos, faltan, escuelas: [], docentes_sm: [], sin_docentes: true } }];
  if (!monday.some(m => m.docente_id)) faltan.push('docentes en Monday (Tablero Subida → Docente/s)');
  else delDoc.forEach(nombre => {
    const m = monday.find(x => calza(x.nombre_monday, nombre));
    if (!m) return faltan.push(`docente en Monday que calce con: ${nombre}`);
    if (!m.pais) return faltan.push(`País del docente ${nombre} en Monday`);
    const cod = BANDERAS[norm(m.pais).trim()];
    if (!cod) return faltan.push(`país sin bandera configurada: ${m.pais} (${nombre})`);
    docentes_sm.push({ nombre, pais: m.pais, bandera: `https://flagcdn.com/w160/${cod}.png` });
  });
  return [{ json: { fotos, faltan, escuelas: [], docentes_sm } }];
}

if (!monday.some(m => m.docente_id)) faltan.push('docentes en Monday (Tablero Subida → Docente/s)');
else delDoc.forEach((nombre, i) => {
  const m = monday.find(x => calza(x.nombre_monday, nombre));
  if (!m) return faltan.push(`docente en Monday que calce con: ${nombre}`);
  if (!m.carpeta_id) return faltan.push(`Carpeta Docente de ${nombre}`);
  if (!m.otras) return faltan.push(`carpeta "Otras fotos" de ${nombre}`);
  const sf = m.archivos
    .map(f => ({ f, v: +(((f.name || '').match(/_SF_V(\d+)/i) || [])[1] || 0) }))
    .filter(x => x.v > 0 && !/folder/.test(x.f.mimeType || ''))
    .sort((a, b) => b.v - a.v)[0];
  if (!sf) return faltan.push(`foto _SF_ de ${nombre}`);
  fotos.push({ n: i + 1, nombre, nombre_catalogo: m.nombre_catalogo || nombre, file_id: sf.f.id, archivo: sf.f.name, pronombre: m.pronombre || '' });
});

const escuelas = (carpetas[0] || {}).escuelas || [];
return [{ json: { fotos, faltan, escuelas } }];

// Une cada imagen generada con su nombre de archivo. El catálogo sale en PNG y WEBP (misma imagen, 1 solo crédito)
// Si la pieza trae carpeta de destino (RRSS de Sesión Magistral → carpeta del país), la pasa a "Subir piezas a Drive".
// Toma los nombres del nodo que armó el HTML: sesión (Sesión Magistral), curso o piezas (seminario)
const fuente = ['Armar HTML V2', 'Armar HTML acreditación', 'Armar HTML diplomado', 'Armar HTML especialización', 'Armar HTML sesión', 'Armar HTML curso', 'Armar HTML piezas'].find(n => { try { return $(n).isExecuted; } catch (e) { return false; } });
const armado = $(fuente).all().map(i => i.json);
const salida = [];
$input.all().forEach((it, i) => {
  const a = armado[i] || {};
  const base = a.nombre_base || String(a.nombre_archivo || '').replace(/\.png$/i, '');
  for (const f of (a.formatos || ['png'])) {
    salida.push({ json: { url: f === 'png' ? it.json.url : `${it.json.url}.${f}`, nombre_archivo: `${base}.${f}`, ...(a.carpeta_id ? { carpeta_id: a.carpeta_id } : {}) }, pairedItem: { item: i } });
  }
});
return salida;

// Arma el HTML de las 5 piezas (3 RRSS, SW en PNG y WEBP, YouTube) con los datos del Documento Maestro, el doodle, las fotos de docentes y los países.
// Banderas, logo e ícono: provisorios incrustados (base64) hasta tener los recursos de diseño.
const R = {"bandera_cl": "data:image/png;base64,", "logo_adipa": "data:image/png;base64,", "icono_certificado": "data:image/png;base64,", "bandera_co": "data:image/svg+xml;base64,", "bandera_mx": "data:image/svg+xml;base64,", "bandera_ar": "data:image/svg+xml;base64,"};
