// Tipo de programa según el prefijo del nombre: [SEMINARIO] … / [CS CL] … (Curso Sincrónico) / [CA CL] … (Curso Asincrónico)
// / [S MAGISTRAL CL] … (Sesión Magistral). Los dos tipos de curso comparten la rama "curso"; "linea" dice qué juego de plantillas usar
const nombre = (it.name || '').trim();
// Diplomado / Postítulo: "[PreLanzamiento Diplo CL] …" o "[Lanzamiento Diplo CL] …" (se revisa antes que Especialización:
// "Postítulo de Especialización…" es Diplomado). Especialización: "[Pre-lanzamiento CL] Especialización …" / "[Lanzamiento CL] Especialización …"
const dip = nombre.match(/^\[\s*(pre-?\s*lanzamiento|lanzamiento)\s+diplo\b/i);
// Acreditación: "[Lanzamiento Acreditación CL] …" (un solo juego, sin prelanzamiento)
const acr = !dip && /^\[\s*(?:pre-?\s*)?lanzamiento\s+acreditaci[oó]n/i.test(nombre);
const esp = !dip && !acr && nombre.match(/^\[\s*(pre-?\s*lanzamiento|lanzamiento)\b[^\]]*\][\s\S]*especializaci[oó]n/i);
const fase = dip || esp ? (/^pre/i.test((dip || esp)[1]) ? 'pre' : 'lanz') : '';
const prefijo = dip ? 'DIP' : acr ? 'AC' : esp ? 'ESP' : (nombre.match(/^\[\s*(SEMINARIO|CS|CA|S\s*MAGISTRAL)\b/i) || [])[1] || '';
const linea = /^S\s*MAGISTRAL$/i.test(prefijo) ? 'SM' : prefijo.toUpperCase();
const tipo = linea === 'SEMINARIO' ? 'seminario' : linea === 'SM' ? 'sesion' : linea === 'ESP' ? 'especializacion' : linea === 'DIP' ? 'diplomado' : linea === 'AC' ? 'acreditacion' : linea ? 'curso' : '';
// Sesión Magistral: país del ítem ([S MAGISTRAL CL] / [S MAGISTRAL MX] / [S MAGISTRAL CO]). CL genera todas las piezas;
// MX y CO solo las 3 RRSS (con los nombres de su Documento Maestro). Sin país → CL
const pais_sm = tipo === 'sesion' ? ((nombre.match(/^\[\s*S\s*MAGISTRAL\s+(CL|MX|CO)\b/i) || [])[1] || 'CL').toUpperCase() : '';

const doc_texto = col('lookup_mm6471ev').display_value || '';      // Doc Maestro (espejo)
const doc_url = url(doc_texto);
const pais_doc = (doc_texto.split(/https?:\/\//)[0].match(/\b(CL|MX|CO|AR)\b/) || [])[1] || ''; // "Documento Maestro CL - …"
