const d = $('Extraer etiquetas').first().json;
const docentes = ($('Elegir foto SF').first().json.docentes_sm || []).slice(0, 3)
  .map(x => ({ nombre: x.nombre, bandera: x.bandera }));
const fotos = $('POPUP a base64').first().json.popup;

// Fondo (FONDO.png achicado a JPG) → base64
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = $input.first().binary.data.mimeType || 'image/jpeg';
const fondo = `data:${mime};base64,${buf.toString('base64')}`;

const datos = { nombre_programa: d.nombre_programa, docentes, fotos, fondo, logo_adipa: R.logo_adipa, logo_psy: R.logo_psy };
const json = o => JSON.stringify(o).replace(/</g, '\\u003c');

// País del ítem: CL arma las 5 piezas; MX y CO solo las 3 RRSS. Las RRSS van a la carpeta del país;
// catálogo y SW, a "Gráficas programa"
const pais = $('Datos de Monday').first().json.pais_sm || 'CL';
const carpeta_pais = $('Validar datos').first().json.carpeta_pais_id;
const carpeta_base = $('Buscar carpeta Gráficas programa').first().json.id;
const esRRSS = nombre => /-RRSS$/.test(nombre);

// Un ítem por pieza: los nodos siguientes se ejecutan una vez por pieza
return Object.entries(PLANTILLAS).filter(([nombre]) => pais === 'CL' || esRRSS(nombre)).map(([nombre, p]) => ({
  json: {
    // El catálogo no usa el fondo: se omite para que pese menos
    html: p.html.replace('__DATOS__', () => json(nombre.includes('CATALOGO') ? { ...datos, fondo: '' } : datos)),
    ancho: p.w,
    alto: p.h,
    nombre_base: nombre,
    carpeta_id: esRRSS(nombre) ? carpeta_pais : carpeta_base,
    formatos: p.formatos,
  },
  pairedItem: { item: 0 },
}));

