const dm = $('Datos de Monday').first().json;
const ex = $('Extraer etiquetas').first().json;
const sel = $('Elegir foto SF').first().json;
const popup = $('Lista fotos docentes').first().json.doodle;   // 1200X1200-POPUP (sin contorno; la plantilla agrega contorno y teñido)

// Foto _SF_ del director (primer ítem de entrada, ya achicada) → base64
let foto_docente = '';
if ($input.all().length && $input.first().binary && $input.first().binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  foto_docente = `data:${$input.first().binary.data.mimeType || 'image/png'};base64,${buf.toString('base64')}`;
}

// Escuela(s) → logo
const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const CODIGOS = { 'salud mental adultos': 'SMA', 'salud mental infantojuvenil': 'SMIJ', 'psicologia organizacional': 'PO', 'psicosocial juridica': 'PSJ', 'educacion y neurodesarrollo': 'EN' };
const escuelas = (sel.escuelas || []).map(e => CODIGOS[Object.keys(CODIGOS).find(k => norm(e).includes(k))]).filter(Boolean).slice(0, 2).map(c => R['logo_' + c]);

const pre = dm.fase === 'pre';
const descuento = pre && ex.precio_normal ? String(Math.round((1 - ex.precio_pre / ex.precio_normal) * 100)) : '';
const datos = {
  nombre_programa: ex.nombre_programa,
  docente: ((sel.fotos || [])[0] || {}).nombre || (ex.docentes || [])[0] || '',
  pronombre: ((sel.fotos || [])[0] || {}).pronombre || '',   // "Pronombre(s)" del director(a) en Monday → Director / Directora / Dirección
  horas_certificadas: ex.horas_certificadas,
  prelanzamiento: pre,
  descuento,
  escuelas,
  foto_docente,
  popup,
  logo_adipa: R.logo_adipa,
};
const json = o => JSON.stringify(o).replace(/</g, '\\u003c');

// Piezas según la fase: Pre-lanzamiento → 3 RRSS como -PL + catálogo + SW; Lanzamiento → 3 RRSS
const RRSS = ['1080X1920-RRSS', '1200X1200-RRSS', '1200X628-RRSS'];
const lista = pre
  ? [...RRSS.map(n => [n, n.replace('-RRSS', '-PL'), ['png']]), ['1200X1200-CATALOGO', '1200X1200-CATALOGO', ['png', 'webp']], ['1200X675-SW', '1200X675-SW', ['png', 'webp']]]
  : RRSS.map(n => [n, n, ['png']]);

// Un ítem por pieza (catálogo y SW van sin sello)
return lista.map(([plantilla, nombre, formatos]) => {
  const p = PLANTILLAS[plantilla];
  const dat = RRSS.includes(plantilla) ? datos : { ...datos, prelanzamiento: false };
  return {
    json: { html: p.html.replace('__DATOS__', () => json(dat)), ancho: p.w, alto: p.h, nombre_base: nombre, formatos },
    pairedItem: { item: 0 },
  };
});

// Diplomado: guarda la ilustración horizontal (ya achicada) y la foto _SF_ del director en base64,
// y deja el id de la ilustración vertical (1080X1920-POPUP) para descargarla si existe
const popup = $('Lista fotos docentes').first().json.doodle;
let foto_docente = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  foto_docente = `data:${$input.first().binary.data.mimeType || 'image/png'};base64,${buf.toString('base64')}`;
} catch (e) {}
const popup_v_id = $('Validar datos').first().json.popup_v_id || '';
return [{ json: { popup, foto_docente, popup_v_id: popup_v_id || 'sin-vertical' } }];

