slice(k + 1).trim())}`; })();\n\n  // \"Viernes 05 de marzo de 2027\" (o \"2027-03-05\") → \"Marzo 2027\"\n  const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];\n  const mesAnio = f => {\n    f = String(f || '').toLowerCase();\n    const iso = f.match(/(\\d{4})-(\\d{2})-\\d{2}/);\n    let mes = -1, anio = '';\n    if (iso) { anio = iso[1]; mes = +iso[2] - 1; }\n    else { mes = MESES.findIndex(x => f.includes(x)); anio = (f.match(/\\b(20\\d{2})\\b/) || [])[1] || ''; }\n    return mes < 0 ? '' : `${MESES[mes][0].toUpperCase() + MESES[mes].slice(1)} ${anio}`.trim();\n  };\n  document.querySelectorAll('.mes').forEach(x => x.textContent = mesAnio(d.fecha_inicio));\n  document.querySelectorAll('.horas').forEach(x => x.textContent = `${parseInt(d.horas_certificadas, 10) || ''} Horas`);\n  document.querySelectorAll('.pct').forEach(el => el.innerHTML = `${esc(d.descuento)}%<br>DCTO.`);\n  document.querySelectorAll('img.adipa').forEach(i => i.src = d.logo_adipa);\n  document.querySelectorAll('img.cal').forEach(i => i.src = d.icono_calendario);\n  // SW: siempre la horizontal completa, como el archivo 1920X1080-POPUP (sin zoom ni recorte): se calcula la medida\n  // a partir del tamaño real de la imagen y se encaja entera, centrada\n  document.querySelectorAll('img.sw').forEach(i => {\n    i.onload = () => {\n      const k = Math.min(1200 / i.naturalWidth, 675 / i.naturalHeight), w = i.naturalWidth * k, h = i.naturalHeight * k;\n      i.style.width = w + 'px'; i.style.height = h + 'px'; i.style.left = (1200 - w) / 2 + 'px'; i.style.top = (675 - h) / 2 + 'px';\n    };\n    i.src = d.popup;\n  });\n\n  // RRSS / PL: capa #674FF8 (manual: 40 % cálidos / 30 % fríos). Ajustado a la referencia: la mitad, en degradado vertical\n  // (más presencia arriba y abajo, casi transparente al centro)\n  const tintar = im => {\n    const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n    const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n    const id = g.getImageData(0, 0, c.width, c.height), p = id.data;\n    const W = c.width, H = c.height;\n    for (let k = 0; k < p.length; k += 4) {\n      const y = (k / 4 / W | 0) / H, borde = Math.pow(Math.abs(y - 0.5) * 2, 1.6);   // 0 al centro, 1 arriba/abajo\n      const calido = Math.min(1, Math.max(0, (p[k] - p[k + 2]) / 90 + 0.5));   // rojo > azul → cálido\n      const a = (0.15 + 0.05 * calido) * (0.15 + 0.85 * borde) + 0.25 * borde;\n      p[k] = p[k] * (1 - a) + 0x67 * a; p[k + 1] = p[k + 1] * (1 - a) + 0x4F * a; p[k + 2] = p[k + 2] * (1 - a) + 0xF8 * a;\n    }\n    g.putImageData(id, 0, 0);\n    return c.toDataURL('image/jpeg', 0.9);\n  };\n  // Ilustración: object-fit cover sobre toda su zona, sin deformar. Si diseño entrega la versión vertical\n  // (popup_vertical = 1080X1920-POPUP.png) se usa esa con su propio encuadre (data-pos-v); si no, la horizontal (data-pos-h).\n  const vertical = !!d.popup_vertical;\n  const ubicar = (img, box, src) => { img.src = src; img.style.objectPosition = (vertical ? box.dataset.posV : box.dataset.posH) || 'center'; };\n\n  // Catálogo: director con cargo según \"Pronombre(s)\" del docente en Monday (Ella → Directora, Él → Director, Elle → Dirección);\n  // si viene vacío, según el título (\"Dra.\" → Directora). Y tipo de programa\n  const docente = String(d.docente || '').trim();\n  const titulos = (docente.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)/) || [''])[0];\n  const pron = String(d.pronombre || '').normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().trim().split(/[\\s\\/,]+/)[0];\n  const rol = pron === 'elle' ? 'Dirección' : pron === 'ella' ? 'Directora' : pron === 'el' ? 'Director' : (/\\bDra\\./i.test(titulos) ? 'Directora' : 'Director');\n  const cargo = `${rol} del ${esPost ? 'Postítulo' : 'Diplomado'}`;\n  const nom = $('nombre-doc'); if (nom) nom.innerHTML = `<b>${esc(docente)}</b><br>${cargo}`;\n\n  // Título en cuadro de texto: la letra parte grande y baja hasta que cabe (alto y ancho)\n  const ajustar = (el, arriba, abajo, max, min) => {\n    if (!el) return;\n    el.innerHTML = tituloHTML;\n    let fs = max;\n    const poner = () => { el.style.fontSize = fs + 'px'; el.style.lineHeight = Math.round(fs * 1.26) + 'px'; };\n    poner();\n    while ((el.offsetHeight > abajo - arriba || el.scrollWidth > el.clientWidth + 1) && fs > min) { fs -= 1; poner(); }\n    el.style.top = arriba + 'px';\n    return el.offsetTop + el.offsetHeight;\n  };\n  // Coloca un bloque justo debajo del anterior\n  const debajo = (el, y) => { if (el) el.style.top = Math.round(y) + 'px'; };\n\n  // Foto del docente en círculo: recorte cuadrado centrado en la cabeza\n  const cargar = src => new Promise(res => { const im = new Image(); im.onload = () => res(im); im.onerror = () => res(null); im.src = src; });\n  const retrato = im => {\n    if (!im) return '';\n    try {\n      const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n      const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n      const px = g.getImageData(0, 0, c.width, c.height).data, a = (x, y) => px[(y * c.width + x) * 4 + 3] > 10;\n      let y0 = -1, y1 = -1, x0 = c.width, x1 = -1;\n      for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) if (a(x, y)) { if (y0 < 0) y0 = y; y1 = y; if (x < x0) x0 = x; if (x > x1) x1 = x; }\n      if (y0 < 0) return im.src;\n      const h = y1 - y0 + 1, w = x1 - x0 + 1, lado = Math.round(Math.min(h, Math.max(w * 0.9, h * 0.55)));\n      let sx = 0, n = 0;\n      for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (a(x, y)) { sx += x; n++; }\n      const cx = n ? sx / n : (x0 + x1) / 2;\n      const o = document.createElement('canvas'); o.width = o.height = lado;\n      o.getContext('2d').drawImage(c, cx - lado / 2, y0 - lado * 0.06, lado, lado, 0, 0, lado, lado);\n      return o.toDataURL('image/png');\n    } catch (e) { return im.src; }\n  };\n\n  Promise.all([document.fonts.ready, cargar(d.foto_docente), cargar(d.popup_vertical || d.popup)]).then(([, foto, pop]) => {\n    const box = $('ilus'); if (box && pop) ubicar(box.querySelector('.fg'), box, tintar(pop));\n    const arco = document.querySelector('.arco'); if (arco) ubicar(arco.querySelector('img'), arco, vertical ? d.popup_vertical : d.popup);\n    document.querySelectorAll('img.retrato').forEach(i => i.src = retrato(foto));\n    const apilar = fm => {\n      const fin = ajustar($('titulo'), d.prelanzamiento ? 290 : 378, 620, fm, 20);\n      debajo($('mes'), fin + 28);\n      const finMes = $('mes').offsetTop + $('mes').offsetHeight;\n      if (d.prelanzamiento) { debajo($('sello'), finMes + 56); debajo($('datos-b'), $('sello').offsetTop + $('sello').offsetHeight + 50); }\n      else debajo($('datos-b'), finMes + 88);\n      return $('datos-b').offsetTop + $('datos-b').offsetHeight;\n    };\n    let fm = 34;\n    while (apilar(fm) > 860 && fm > 20) fm -= 1;\n  });\n</script>\n</body>\n</html>\n", "w": 1200, "h": 1200}, "1200X628-RRSS": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1200X628-RRSS — Diplomado</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --oscuro: #091D42; --morado: #704EFC; --cian: #2DB5FD; --amarillo: #FDC660; --gris: #5B5B5B; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1200px; height: 628px; overflow: hidden; }\n  body { font-family: 'Poppins', sans-serif; position: relative; color: var(--oscuro); background: #fff; }\n  .abs { position: absolute; }\n  b { font-weight: 700; }\n\n  /* Ilustración con tinte lila (manual: transparencia #674ff8) */\n  .ilus { overflow: hidden; isolation: isolate; background: #CDB8D2; }\n  .ilus .bg { display: none; }\n  .ilus .fg, .arco img { position: absolute; left: 0; top: 0; wid