oct 2026): sin logo de institución. El texto de certificación del docente lo agrega diseño a mano\n  const conInstitucion = false;\n\n  // Viñeta y título: \"Acreditación Oficial [Clínica] [Internacional] <título>\" → la primera parte va a la viñeta.\n  // Si el nombre no empieza así, la viñeta dice \"Acreditación Oficial\" y el título es el nombre completo\n  const nombre = String(d.nombre_programa || '').trim();\n  const m = nombre.match(/^(acreditaci[oó]n\\s+oficial(?:\\s+(?:cl[ií]nica|internacional))*)\\s+(.+)$/i);\n  const vineta = m ? m[1] : 'Acreditación Oficial';\n  // Se quita \"en/de\" del inicio (\"Acreditación Oficial Internacional en …\") y se deja la primera letra en mayúscula\n  const t0 = (m ? m[2] : nombre).replace(/^(en|de)\\s+/i, '');\n  const titulo = t0.charAt(0).toUpperCase() + t0.slice(1);\n  document.querySelectorAll('.vineta').forEach(v => v.textContent = vineta);\n\n  // \"Sábado 14 de noviembre de 2026\" (o \"2026-11-14\") → \"Noviembre 2026\"\n  const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];\n  const mesAnio = f => {\n    f = String(f || '').toLowerCase();\n    const iso = f.match(/(\\d{4})-(\\d{2})-\\d{2}/);\n    let mes = -1, anio = '';\n    if (iso) { anio = iso[1]; mes = +iso[2] - 1; }\n    else { mes = MESES.findIndex(x => f.includes(x)); anio = (f.match(/\\b(20\\d{2})\\b/) || [])[1] || ''; }\n    return mes < 0 ? '' : `${MESES[mes][0].toUpperCase() + MESES[mes].slice(1)} ${anio}`.trim();\n  };\n  document.querySelectorAll('.mes').forEach(x => x.textContent = mesAnio(d.fecha_inicio));\n\n  // Logos e imágenes\n  document.querySelectorAll('img.adipa').forEach(i => i.src = d.logo_adipa);\n  document.querySelectorAll('img.cal').forEach(i => i.src = d.icono_calendario);\n  const fondoFoto = document.querySelector('.fondo .foto');\n  if (fondoFoto && d.fondo) fondoFoto.style.backgroundImage = `url(\"${d.fondo}\")`;\n\n  // Variante: con institución (logo en