).join(' ');\n    const spans = [...el.querySelectorAll('span')];\n    const lineas = () => new Set(spans.map(s => s.offsetTop)).size;\n    let fs = max;\n    const poner = () => { el.style.fontSize = fs + 'px'; el.style.lineHeight = Math.round(fs * 1.18) + 'px'; };\n    poner();\n    while ((el.offsetHeight > abajo - arriba || lineas() > 2) && fs > min) { fs -= 1; poner(); }\n    el.style.top = Math.round(arriba + (abajo - arriba - el.offsetHeight) / 2) + 'px';\n    if (colorear) { const t0 = spans[0].offsetTop; spans.forEach(s => { if (s.offsetTop > t0) s.classList.add('l2'); }); }\n  };\n\n  // POPUP: se recortan los márgenes transparentes antes de ubicarlo\n  const recortar = src => new Promise(res => {\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res(src);\n        const o = document.createElement('canvas'); o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;\n        o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);\n        res(o.toDataURL('image/png'));\n      } catch (e) { res(src); }\n    };\n    im.onerror = () => res(src);\n    im.src = src;\n  });\n\n  const encoger = (el, maxAncho, min) => { if (!el) return; let fs = parseFloat(getComputedStyle(el).fontSize); while (el.scrollWidth > maxAncho && fs > min) { fs -= 0.5; el.style.fontSize = fs + 'px'; } };\n  Promise.all([document.fonts.ready, recortar(d.popup)]).then(([, pop]) => {\n    document.querySelectorAll('img.popup').f