cial(?:\\s+(?:cl[ií]nica|internacional))*)\\s+(.+)$/i);\n  const vineta = m ? m[1] : 'Acreditación Oficial';\n  // Se quita \"en/de\" del inicio (\"Acreditación Oficial Internacional en …\") y se deja la primera letra en mayúscula\n  const t0 = (m ? m[2] : nombre).replace(/^(en|de)\\s+/i, '');\n  const titulo = t0.charAt(0).toUpperCase() + t0.slice(1);\n  document.querySelectorAll('.vineta').forEach(v => v.textContent = vineta);\n\n  // \"Sábado 14 de noviembre de 2026\" (o \"2026-11-14\") → \"Noviembre 2026\"\n  const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];\n  const mesAnio = f => {\n    f = String(f || '').toLowerCase();\n    const iso = f.match(/(\\d{4})-(\\d{2})-\\d{2}/);\n    let mes = -1, anio = '';\n    if (iso) { anio = iso[1]; mes = +iso[2] - 1; }\n    else { mes = MESES.findIndex(x => f.includes(x)); anio = (f.match(/\\b(20\\d{2})\\b/) || [])[1] || ''; }\n    return mes < 0 ? '' : `${MESES[mes][0].toUpperCase() + MESES[mes].slice(1)} ${anio}`.trim();\n  };\n  document.querySelectorAll('.mes').forEach(x => x.textContent = mesAnio(d.fecha_inicio));\n\n  // Logos e imágenes\n  document.querySelectorAll('img.adipa').forEach(i => i.src = d.logo_adipa);\n  document.querySelectorAll('img.cal').forEach(i => i.src = d.icono_calendario);\n  const fondoFoto = document.querySelector('.fondo .foto');\n  if (fondoFoto && d.fondo) fondoFoto.style.backgroundImage = `url(\"${d.fondo}\")`;\n\n  // Variante: con institución (logo en el círculo) o sencilla (foto del docente en el círculo)\n  document.body.classList.add(conInstitucion ? 'v-inst' : 'v-simple');\n  const circulo = $('circulo');\n  if (circulo) circulo.innerHTML = conInstitucion\n    ? `<img class=\"logo\" src=\"${esc(d.logo_institucion)}\" alt=\"\">`\n    : `<img class=\"foto\" src=\"${esc(d.foto_docente)}\" alt=\"\">`;\n  const txt = $('txt');\n  if (txt) txt.innerHTML = conInstitucion\n    ? `<div class=\"linea corta\"></div><div class=\"cuerpo\">Obtén la <b class=\"m\">acreditación oficial del programa</b> directamente con<br>${esc(d.institucion)}.</div>`\n    : '';   // espacio vacío: diseño agrega \"Certificación emitida por Adipa y <docente>\" + la frase de acreditación\n  document.querySelectorAll('.fecha .doc').forEach(x => x.textContent = conInstitucion ? d.docente : '');\n  document.querySelectorAll('.horas').forEach(x => x.textContent = `${parseInt(d.horas_certificadas, 10) || ''} horas`);\n\n  // Catálogo: docente (foto + nombre) y logo de la institución junto al de ADIPA\n  const fotoCat = $('foto-cat'); if (fotoCat) fotoCat.src = d.foto_docente;\n  // Nombre del docente: títulos (Per. CP. / PhD. Mg. Ps. …) en la primera línea y el nombre en la segunda\n  const partesDoc = n => { n = String(n || '').trim(); const k = n.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)(.+)$/); return k ? [k[1].trim(), k[2].trim()] : null; };\n  const nomCat = $('nombre-cat'); if (nomCat) { const p = partesDoc(d.docente); nomCat.innerHTML = p ? `${esc(p[0])}<br><span class=\"nm\">${esc(p[1])}</span>` : esc(d.docente); }\n  const inst = $('logo-inst'); if (inst && conInstitucion) inst.src = d.logo_institucion_horizontal || d.logo_institucion;\n\n  // Título en cuadro de texto: la letra baja hasta caber (máx. 2 líneas); si ocupa 2 líneas, la segunda va en morado\n  const ajustarTitulo = (el, arriba, abajo, max, min, colorear) => {\n    const palabras = titulo.split(/\\s+/);\n    el.innerHTML = palabras.map(p => `<span>${esc(p)}</span>`).join(' ');\n    const spans = [...el.querySelectorAll('span')];\n    const lineas = () => new Set(spans.map(s => s.offsetTop)).size;\n    let fs = max;\n    const poner = () => { el.style.fontSize = fs + 'px'; el.style.lineHeight = Math.round(fs * 1.18) + 'px'; };\n    poner();\n    while ((el.offsetHeight > abajo - arriba || lineas() > 2) && fs > min) { fs -= 1; poner(); }\n    el.style.top = Math.round(arriba + (abajo - arriba - el.offsetHeight) / 2) + 'px';\n    if (colorear) { const t0 = spans[0].offsetTop; spans.forEach(s => { if (s.offsetTop > t0) s.classList.add('l2'); }); }\n  };\n\n  // POPUP: se recortan los márgenes transparentes antes de ubicarlo\n  const recortar = src => new Promise(res => {\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res(src);\n        const o = document.createElement('canvas'); o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;\n        o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);\n        res(o.toDataURL('image/png'));\n      } catch (e) { res(src); }\n    };\n    im.onerror = () => res(src);\n    im.src = src;\n  });\n\n  const encoger = (el, maxAncho, min) => { if (!el) return; let fs = parseFloat(getComputedStyle(el).fontSize); while (el.scrollWidth > maxAncho && fs > min) { fs -= 0.5; el.style.fontSize = fs + 'px'; } };\n  Promise.all([document.fonts.ready, recortar(d.popup)]).then(([, pop]) => {\n    document.querySelectorAll('img.popup').forEach(i => i.src = pop);\n    document.querySelectorAll('.vineta').forEach(v => encoger(v, parseFloat(getComputedStyle(v).maxWidth) || 2000, 14));\n    const nm = document.querySelector('#nombre-cat .nm');\n    if (nm && nm.getBoundingClientRect().height > parseFloat(getComputedStyle(nm.parentElement).lineHeight) * 1.5) {\n      const p = partesDoc(d.docente), k = p[1].indexOf(' ');\n      if (k > 0) $('nombre-cat').innerHTML = `${esc(p[0])} ${esc(p[1].slice(0, k)