      if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res(src);\n        const o = document.createElement('canvas'); o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;\n        o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);\n        res(o.toDataURL('image/png'));\n      } catch (e) { res(src); }\n    };\n    im.onerror = () => res(src);\n    im.src = src;\n  });\n\n  const encoger = (el, maxAncho, min) => { if (!el) return; let fs = parseFloat(getComputedStyle(el).fontSize); while (el.scrollWidth > maxAncho && fs > min) { fs -= 0.5; el.style.fontSize = fs + 'px'; } };\n  Promise.all([document.fonts.ready, recortar(d.popup)]).then(([, pop]) => {\n    document.querySelectorAll('img.popup').forEach(i => i.src = pop);\n    document.querySelectorAll('.vineta').forEach(v => encoger(v, parseFloat(getComputedStyle(v).maxWidth) || 2000, 14));\n    const nm = document.querySelector('#nombre-cat .nm');\n    if (nm && nm.getBoundingClientRect().height > parseFloat(getComputedStyle(nm.parentElement).lineHeight) * 1.5) {\n      const p = partesDoc(d.docente), k = p[1].indexOf(' ');\n      if (k > 0) $('nombre-cat').innerHTML = `${esc(p[0])} ${esc(p[1].slice(0, k))}<br>${esc(p[1].slice(k + 1))}`;\n    }\n    const em = document.querySelector('.txt .emitida'); if (em) encoger(em, em.parentElement.clientWidth, 12);\n\n  });\n</script>\n</body>\n</html>\n", "w": 1200, "h": 675, "formatos": ["png", "webp"]}};

const ex = $('Extraer etiquetas').first().json;
const sel = $('Elegir foto SF').first().json;
const ins = $('Insumos acreditación').first().json;

// FONDO.png (achicado) → base64
let fondo = '';
const e = $input.first();
if (e && e.binary && e.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  fondo = `data:${e.binary.data.mimeType || 'image/jpeg'};base64,${buf.toString('base64')}`;
}

const datos = {
  nombre_programa: ex.nombre_programa,
  fecha_inicio: ex.fecha_inicio,
  horas_certificadas: ex.horas_certificadas,
  docente: ((sel.fotos || [])[0] || {}).nombre || (ex.docentes || [])[0] || '',
  foto_docente: ins.foto_docente,
  acreditacion_docente: '',
  institucion: '',
  logo_institucion: '',
  logo_institucion_horizontal: '',
  popup: ins.popup,
  fondo,
  logo_adipa: R.logo_adipa,
  icono_calendario: R.icono_calendario,
};
const json = o => JSON.stringify(o).replace(/</g, '\\u003c');

// Un ítem por pieza (el catálogo no usa el fondo: se omite para que pese menos)
return Object.entries(PLANTILLAS).map(([nombre, p]) => ({
  json: {
    html: p.html.replace('__DATOS__', () => json(nombre.includes('CATALOGO') ? { ...datos, fondo: '' } : datos)),
    ancho: p.w,
    alto: p.h,
    nombre_base: nombre,
    formatos: p.formatos,
  },
  pairedItem: { item: 0 },
}));

// Arma las piezas especiales de la VERSIÓN 2: cuadrada 1200X1200-RRSS-V2 e historia 1080X1920-RRSS-V2, una plantilla por línea (Plantillas HTML/v2/<línea>/).
