const PLANTILLAS = {"seminario": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1200X1200-RRSS-V2 — Seminario</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --morado: #6F4EFC; --amarillo: #FAC167; --oscuro: #01143B; --cian: #2EB6FF; --linea: #1DBAFF; --fondo: #CAE8FF; --nombre: #6E45A8; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1200px; height: 1200px; overflow: hidden; }\n  body { font-family: 'Poppins', sans-serif; background: var(--fondo); position: relative; color: var(--oscuro); }\n  .abs { position: absolute; }\n  b { font-weight: 700; }\n\n  /* Fondo: ondas suaves (provisorio, aproximación al diseño) */\n  .ondas { left: 0; top: 0; width: 1200px; height: 1200px; }\n\n  .logo { left: 84px; top: 51px; width: 255px; height: 96px; border-radius: 14px; background: #fff; display: flex; align-items: center; justify-content: center; }\n  .logo img { height: 52px; display: block; }\n\n  .pill-sem { left: 64px; top: 176px; height: 83px; padding: 0 70px 0 30px; border-radius: 42px; background: var(--morado); color: #fff; font-weight: 700; font-size: 46px; line-height: 85px; white-space: nowrap; }\n  .pill-gra { top: 176px; height: 83px; padding: 0 22px; border-radius: 42px; background: var(--amarillo); color: var(--morado); font-weight: 700; font-size: 46px; line-height: 79px; border: 3px solid var(--morado); white-space: nowrap; }\n\n  .titulo { left: 86px; top: 300px; width: 860px; color: var(--oscuro); font-weight: 400; }\n\n  /* ¿Qué aprenderás? */\n  .barra { left: 86px; width: 10px; border-radius: 5px; background: var(--linea); }\n  .que { left: 137px; color: var(--morado); font-weight: 700; font-size: 39px; line-height: 46px; }\n  .aprend { left: 137px; width: 445px; display: flex; flex-direction: column; }\n  .aprend .item { position: relative; color: var(--oscuro); font-weight: 500; }\n  .aprend .check { position: absolute; left: -62px; top: 0; width: 38px; height: 38px; border-radius: 50%; background: #fff; border: 2.5px solid var(--morado); display: flex; align-items: center; justify-content: center; }\n  .aprend .check svg { width: 20px; height: 20px; }\n\n  .fecha { left: 142px; display: flex; align-items: baseline; gap: 14px; color: var(--oscuro); font-weight: 700; white-space: nowrap; }\n  .fecha .n { font-size: 58px; line-height: 64px; } .fecha .m { font-size: 37px; line-height: 44px; }\n  .subraya { left: 122px; width: 364px; height: 3px; background: var(--morado); }\n  .horas { left: 133px; display: flex; flex-direction: column; color: var(--oscuro); font-weight: 600; }\n  .horas .fila { display: flex; align-items: center; gap: 16px; white-space: nowrap; }\n  .horas img { width: 60px; height: 40px; object-fit: cover; display: block; border-radius: 4px; box-shadow: 0 0 0 1px rgba(1,20,59,.12); }\n  .horas.varios .fila { gap: 12px; } .horas.varios img { width: 39px; height: 26px; border-radius: 3px; }\n\n  /* Docentes: círculo cian + fotos grandes recortadas (sin fondo) */\n  .circulo { left: 624px; top: 487px; width: 820px; height: 820px; border-radius: 50%; background: var(--cian); }\n  .fotos { left: 0; top: 0; width: 1200px; height: 1200px; }\n  .fotos img { display: block; object-fit: contain; object-position: center bottom; }\n  .caja { z-index: 5; left: 613px; top: 994px; width: 474px; min-height: 138px; border-radius: 30px; background: var(--amarillo); padding: 20px 34px; display: flex; flex-direction: column; justify-content: center; }\n  .caja .lbl { color: #4A2BC9; font-weight: 700; font-size: 30px; line-height: 36px; }\n  .caja .nom { color: var(--morado); font-weight: 700; font-size: 33px; line-height: 40px; }\n  .caja .rol { color: #4A2BC9; font-weight: 700; font-size: 30px; line-height: 36px; }\n</style>\n</head>\n<body>\n\n<!-- ===== DATOS: n8n reemplaza este bloque con los datos del programa ===== -->\n<script id=\"datos\" type=\"application/json\">__DATOS__</script>\n<!-- ======================================================================= -->\n\n<svg class=\"abs ondas\" viewBox=\"0 0 1200 1200\" fill=\"none\">\n  <path d=\"M-80 420 C 160 300, 220 80, 460 -40\" stroke=\"#D9EFFD\" stroke-width=\"150\" stroke-linecap=\"round\"/>\n  <path d=\"M620 60 C 760 -40, 980 -20, 1080 120 C 1180 260, 1080 400, 960 470\" stroke=\"#D9EFFD\" stroke-width=\"130\" stroke-linecap=\"round\"/>\n  <path d=\"M-60 1080 C 120 1000, 260 1120, 380 1260\" stroke=\"#D9EFFD\" stroke-width=\"140\" stroke-linecap=\"round\"/>\n</svg>\n<div class=\"abs circulo\"></div>\n<div class=\"abs fotos\" id=\"fotos\"></div>\n\n<div class=\"abs logo\"><img id=\"logo\" alt=\"\"></div>\n<div class=\"abs pill-sem\" id=\"pill-sem\">Seminario Online</div>\n<div class=\"abs pill-gra\" id=\"pill-gra\">Gratuito</div>\n\n<div class=\"abs titulo\" id=\"titulo\"></div>\n\n<div class=\"abs barra\" id=\"barra\"></div>\n<div class=\"abs que\" id=\"que\">¿Qué aprenderás?</div>\n<div class=\"abs aprend\" id=\"aprend\"></div>\n\n<div class=\"abs fecha\" id=\"fecha\"><span class=\"n\" id=\"dia\"></span><span class=\"m\" id=\"mes\"></span></div>\n<div class=\"abs subraya\" id=\"subraya\"></div>\n<div class=\"abs horas\" id=\"horas\"></div>\n\n<div class=\"abs caja\" id=\"caja\"></div>\n\n<script>\n  const d = JSON.parse(document.getElementById('datos').textContent);\n  const esc = s => String(s == null ? '' : s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const $ = id => document.getElementById(id);\n  const MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];\n  $('logo').src = d.logo_adipa;\n\n  // Píldora \"Gratuito\" pegada a la de \"Seminario Online\"\n  const ps = $('pill-sem'); $('pill-gra').style.left = (ps.offsetLeft + ps.offsetWidth - 42) + 'px';\n\n  // Título: negrita hasta el primer \":\" o \"?\" (incluido); sin ninguno → todo en negrita\n  const t = String(d.nombre_programa || '').trim(), k = t.search(/[:?]/);\n  $('titulo').innerHTML = k < 0 ? `<b>${esc(t)}</b>` : `<b>${esc(t.slice(0, k + 1))}</b> ${esc(t.slice(k + 1).trim())}`;\n\n  // Fecha \"2026-11-05\" → \"05 Noviembre\"\n  const [, mm, dd] = String(d.fecha || '').split('-').map(Number);\n  $('dia').textContent = String(dd || '').padStart(2, '0'); $('mes').textContent = MESES[(mm || 1) - 1];\n\n  // Horas: una fila por país (bandera + \"20:00 hrs. CHI\", como en la V1)\n  const paises = d.paises || [];\n  if (paises.length > 1) $('horas').classList.add('varios');\n  $('horas').innerHTML = paises.map(p => `<div class=\"fila\"><img src=\"${esc(p.bandera)}\" alt=\"\"><span>${esc(p.hora)} hrs. ${esc(p.sigla)}</span></div>`).join('');\n\n  // ¿Qué aprenderás? (los genera la IA desde [objetivos_especificos]; máx. 2)\n  const check = '<svg viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"#6F4EFC\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 10.5l4 4 8-9\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 2).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Docentes (máx. 2): caja amarilla con nombre(s)\n  const docs = (d.docentes || []).filter(x => x.nombre && x.nombre.trim()).slice(0, 2);\n  $('caja').innerHTML = docs.length > 1\n    ? `<div class=\"lbl\">Docentes</div>${docs.map(x => `<div class=\"nom\">${esc(x.nombre.trim())}</div>`).join('')}`\n    : `<div class=\"nom\">${esc((docs[0] || {}).nombre || '')}</div><div class=\"rol\">Docente</div>`;\n\n  // Foto del docente como retrato de busto (cabeza y pecho), aunque la _SF_ sea de cuerpo entero:\n  // se recortan los márgenes transparentes y la altura se limita a ~1,25 veces el ancho de los hombros\n  const recortar = src => new Promise(res => {\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight });\n        const w = x1 - x0 + 1, h = Math.min(y1 - y0 + 1, Math.round(w * 1.25));\n        // centro de la cabeza: promedio horizontal de la silueta en el 18 % superior\n        let sx = 0, n = 0;\n        for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5 });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  // ¿Algún texto invade el círculo celeste? (centro 1034,897; radio 410 + 24 px de margen)\n  const chocaCirculo = el => {\n    const r = document.createRange(); r.selectNodeContents(el);\n    return [...r.getClientRects()].some(q => {\n      const cx = Math.max(q.left, Math.min(1034, q.right)), cy = Math.max(q.top, Math.min(897, q.bottom));\n      return Math.hypot(cx - 1034, cy - 897) < 434;\n    });\n  };\n  // Bloque izquierdo, en 3 zonas que no se pisan:\n  //  1) Título: letra de 54 px que baja solo si no cabe en 4 líneas o toca el círculo.\n  //  2) Fecha y horas: ancladas abajo (suben si hay más países).\n  //  3) ¿Qué aprenderás?: ocupa todo el espacio entre el título y la fecha; la letra crece o se achica para llenarlo.\n  //  La línea celeste va desde \"¿Qué aprenderás?\" hasta la fecha.\n  const ajustar = () => {\n    const tit = $('titulo'), ap = $('aprend');\n    let fs = 54;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.2) + 'px'; };\n    ponerT();\n    while ((tit.offsetHeight > Math.round(fs * 1.2) * 4 + 2 || chocaCirculo(tit)) && fs > 38) { fs -= 1; ponerT(); }\n\n    // Fecha y horas, ancladas abajo\n    const varios = paises.length > 1, altoHoras = varios ? paises.length * 34 : 46;\n    $('horas').style.fontSize = (varios ? 24 : 40) + 'px';\n    $('horas').style.lineHeight = (varios ? 34 : 46) + 'px';\n    const yHoras = 1160 - altoHoras, yFecha = yHoras - 18 - 3 - 14 - 64;\n    $('fecha').style.top = yFecha + 'px';\n    $('subraya').style.top = (yFecha + 64 + 14) + 'px';\n    $('horas').style.top = yHoras + 'px';\n\n    // ¿Qué aprenderás?\n    const yQue = tit.offsetTop + tit.offsetHeight + 36;\n    $('que').style.top = yQue + 'px';\n    const apTop = yQue + 62, apMax = yFecha - 34;\n    ap.style.top = apTop + 'px';\n    let fa = 30;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.3) + 'px'; ap.style.gap = Math.round(fa * 1.1) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.3 - 38) / 2) + 'px');\n    };\n    ponerA();\n    while ((apTop + ap.offsetHeight > apMax || chocaCirculo(ap)) && fa > 15) { fa -= 0.5; ponerA(); }\n\n    // Línea celeste: desde \"¿Qué aprenderás?\" hasta la fecha\n    $('barra').style.top = (yQue - 14) + 'px';\n    $('barra').style.height = (yFecha - 6 - (yQue - 14)) + 'px';\n    // Caja amarilla: más alta si son 2 docentes\n    const caja = $('caja'); caja.style.top = (1132 - caja.offsetHeight) + 'px';\n  };\n\n  Promise.all([document.fonts.ready, ...docs.map(x => recortar(x.foto))]).then(([, ...fotos]) => {\n    fotos = fotos.filter(Boolean);\n    // Retratos apoyados abajo