n/de\"; negrita hasta los \":\" (incluidos); sin \":\" todo en negrita\n  const t0 = nombre.replace(/^(diplomado|post[ií]tulo)\\s+(en|de)\\s+/i, '');\n  const t = t0.charAt(0).toUpperCase() + t0.slice(1), k = t.indexOf(':');\n  $('titulo').innerHTML = k < 0 ? `<b>${esc(t)}</b>` : `<b>${esc(t.slice(0, k + 1))}</b> ${esc(t.slice(k + 1).trim())}`;\n\n  // Fecha: \"Martes 22 de septiembre de 2026\" o \"2026-09-22\" → \"22 / SEPTIEMBRE / 2026\"\n  const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];\n  const f = String(d.fecha_inicio || '').toLowerCase();\n  let dia = '', mes = -1, anio = '';\n  const iso = f.match(/(\\d{4})-(\\d{2})-(\\d{2})/);\n  if (iso) { anio = iso[1]; mes = +iso[2] - 1; dia = iso[3]; }\n  else { mes = MESES.findIndex(x => f.includes(x)); anio = (f.match(/\\b(20\\d{2})\\b/) || [])[1] || ''; dia = (f.match(/\\b(\\d{1,2})\\b/) || [])[1] || ''; }\n  $('dia').textContent = dia ? String(dia).padStart(2, '0') : '';\n  $('mes').textContent = mes >= 0 ? MESES[mes] : '';\n  $('anio').textContent = anio;\n\n  // ¿Qué aprenderás? (la IA los resume desde [objetivos_especificos]; máx. 2)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 2).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Director(a) del programa: según \"Pronombre(s)\" del docente en Monday (Ella → Directora, Él → Director, Elle → Dirección);\n  // si viene vacío, según el título (\"Dra.\" → Directora), igual que la versión 1\n  const doc = d.docente || {};\n  const nomDoc = String(doc.nombre || '').trim();\n  const titulos = (nomDoc.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)/) || [''])[0];\n  $('dir-nom').textContent = nomDoc;\n  const pron = String(d.pronombre || '').normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().trim().split(/[\\s\\/,]+/)[0];\n  const rol = pron === 'elle' ? 'Dirección' : pron === 'ella' ? 'Directora' : pron === 'el' ? 'Director' : (/\\bDra\\./i.test(titulos) ? 'Directora' : 'Director');\n  $('dir-cargo').textContent = `${rol} del programa`;\n\n  // Foto: retrato de busto (cabeza y pecho), centrado por la cabeza\n  const recortar = src => new Promise(res => {\n    if (!src) return res(null);\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5, cab: 0.45 });\n        const w = x1 - x0 + 1, h = Math.min(y1 - y0 + 1, Math.round(w * 1.25));\n        let sx = 0, n = 0, cab = 0;\n        for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        for (let y = y0; y < y0 + h * 0.25; y++) { let a = -1, b = -1; for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { if (a < 0) a = x; b = x; } if (b - a > cab) cab = b - a; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5, cab: cab / w });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5, cab: 0.45 }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título (285–440): la letra baja hasta que cabe; debajo, la línea morada\n    const tit = $('titulo'); let fs = 46;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.22) + 'px'; };\n    ponerT(); while (tit.offsetHeight > 165 && fs > 28) { fs -= 1; ponerT(); }\n    tit.style.top = '285px';\n    const finT = 285 + tit.offsetHeight;\n    $('subr').style.top = (finT + 14) + 'px';\n    // ¿Qué aprenderás? desde la línea morada hasta la fecha (930); la letra se adapta al espacio\n    const top = finT + 50;\n    $('barra').style.top = top + 'px'; $('barra').style.height = (932 - top) + 'px';\n    $('que').style.top = (top + 6) + 'px';\n    const ap = $('aprend'), apTop = top + 82; ap.style.top = apTop + 'px';\n    let fa = 30;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.2) + 'px'; ap.style.gap = Math.round(fa * 1.4) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.2 - 60) / 2 + 2) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > 920 - apTop && fa > 14) { fa -= 0.5; ponerA(); }\n    // Nombre del director(a): la letra baja si es largo (máx. 2 líneas)\n    const nom = $('dir-nom'); let fn = 30;\n    const ponerN = () => { nom.style.fontSize = fn + 'px'; nom.style.lineHeight = Math.round(fn * 1.2) + 'px'; };\n    ponerN(); while (nom.offsetHeight > Math.round(fn * 1.2) * 2 + 1 && fn > 20) { fn -= 1; ponerN(); }\n  };\n\n  Promise.all([document.fonts.ready, recortar(doc.foto)]).then(([, f]) => {\n    // Cabeza centrada en x = 915; tamaño según el ancho de la cabeza (≈ 230 px); el busto termina en el borde inferior del círculo\n    if (f) {\n      const alto = Math.max(520, Math.min(700, Math.round(230 / ((f.cab || 0.45) * f.w) * f.h)));\n      const w = Math.round(alto * f.w / f.h);\n      $('foto').innerHTML = `<img src=\"${f.src}\" style=\"position:absolute;top:${926 - alto}px;height:${alto}px;width:${w}px;left:${Math.round(915 - f.cx * w)}px\">`;\n    }\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1200, "h": 1200}, "especializacion": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1200X1200-RRSS-V2 — Especialización</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --morado: #6F4FFB; --morado-txt: #6F51F2; --cian: #2FB5FC; --linea: #25B6F6; --amarillo: #FEC85E; --lila: #F0EDFF; --oscuro: #0A1C42; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1200px; height: 1200px; overflow: hidden; }\n  body { font-family: 'Poppins', sans-serif; background: #fff; position: relative; color: var(--oscuro); }\n  .abs { position: absolute; }\n\n  /* Formas de esquina */\n  .amar1 { left: 848px; top: -40px; width: 200px; height: 135px; border-radius: 0 0 0 32px; background: var(--amarillo); }\n  /* Forma en U: arriba recta, abajo semicírculo */\n  .mor1 { left: 940px; top: -60px; width: 252px; height: 345px; border-radius: 0 0 126px 126px; background: var(--morado); }\n  .cian1 { left: -50px; top: 1020px; width: 180px; height: 180px; border-radius: 50%; background: var(--cian); }\n\n  .logo { left: 97px; top: 95px; height: 58px; display: block; }\n\n  /* Título: \"ESPECIALIZACIÓN EN …:\" en morado; lo que va después de \":\" en recuadros morados */\n  .pre { left: 80px; width: 680px; color: var(--morado-txt); font-weight: 400; text-transform: uppercase; }\n  .dest { left: 66px; width: 720px; text-transform: uppercase; font-weight: 700; color: #fff; }\n  .dest span { background: var(--morado); border-radius: 12px; padding: 0 14px; -webkit-box-decoration-break: clone; box-decoration-break: clone; }\n\n  /* Foto del director(a) en círculo lila */\n  .circulo { left: 568px; top: 350px; width: 680px; height: 680px; border-radius: 50%; background: var(--lila); }\n  /* La foto se recorta por la mitad de abajo del círculo; arriba puede salir (cabeza y hombros). Contorno blanco como en el diseño */\n  .foto { left: 0; top: 0; width: 1200px; height: 1200px; clip-path: path('M 540 0 H 1200 V 690 H 540 Z M 568 690 A 340 340 0 0 1 1248 690 A 340 340 0 0 1 568 690 Z'); }\n  .foto img { filter: drop-shadow(9px 0 0 #fff) drop-shadow(-9px 0 0 #fff) drop-shadow(0 9px 0 #fff) drop-shadow(0 -9px 0 #fff); }\n\n  /* ¿Qué aprenderás? */\n  .barra { left: 70px; width: 10px; border-radius: 5px; background: var(--linea); }\n  .que { left: 122px; color: var(--morado-txt); font-weight: 700; font-size: 38px; line-height: 48px; }\n  /* Zona segura del texto: termina en x = 555, antes del círculo de la foto */\n  .aprend { left: 125px; width: 430px; display: flex; flex-direction: column; }\n  .aprend .item { position: relative; color: var(--oscuro); font-weight: 400; text-align: justify; }\n  .aprend .check { position: absolute; left: -80px; top: 0; width: 58px; height: 58px; border-radius: 50%; background: #fff; border: 2px solid var(--morado-txt); display: flex; align-items: center; justify-content: center; }\n  .aprend .check svg { width: 38px; height: 38px; }\n\n  /* Modalidad */\n  .modal { left: 115px; top: 1068px; width: 560px; height: 170px; border-radius: 0 85px 0 0; background: var(--morado); }\n  .ico { left: 148px; top: 1086px; width: 76px; height: 76px; border-radius: 14px; background: var(--amarillo); display: flex; align-items: center; justify-content: center; }\n  .ico svg { width: 56px; height: 56px; }\n  .mtxt { left: 240px; top: 1082px; color: #fff; }\n  .mtxt .a { font-size: 32px; line-height: 36px; font-weight: 400; }\n  .mtxt .b { font-size: 48px; line-height: 56px; font-weight: 700; }\n\n  /* Director(a): títulos y nombre, con línea amarilla */\n  .dir { left: 740px; bottom: 82px; width: 420px; z-index: 2; }\n  .dir .tt { color: var(--morado-txt); font-weight: 400; font-size: 32px; line-height: 40px; }\n  .dir .nn { color: var(--morado-txt); font-weight: 700; }\n  .lin { left: 735px; top: 1132px; width: 352px; height: 12px; background: var(--amarillo); }\n</style>\n</head>\n<body>\n\n<!-- ===== DATOS: n8n reemplaza este bloque con los datos del programa ===== -->\n<script id=\"datos\" type=\"application/json\">__DATOS__</script>\n<!-- ======================================================================= -->\n\n<div class=\"abs amar1\"></div>\n<div class=\"abs mor1\"></div>\n<div class=\"abs circulo\"></div>\n<div class=\"abs foto\" id=\"foto\"></div>\n\n<img class=\"abs logo\" id=\"logo\" alt=\"\">\n<div class=\"abs pre\" id=\"pre\"></div>\n<div class=\"abs dest\" id=\"dest\"></div>\n\n<div class=\"abs barra\" id=\"barra\"></div>\n<div class=\"abs que\" id=\"que\">¿Qué aprenderás?</div>\n<div class=\"abs aprend\" id=\"aprend\"></div>\n\n<div class=\"abs cian1\"></div>\n<div class=\"abs modal\"></div>\n<div class=\"abs ico\">\n  <!-- Ícono provisorio: reemplazar por el original de diseño -->\n  <svg viewBox=\"0 0 56 56\" fill=\"none\" stroke=\"#6F4FFB\" stroke-width=\"2.4\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><rect x=\"9\" y=\"12\" width=\"38\" height=\"26\" rx=\"2\"/><path d=\"M4 44h48M22 44v-2h12v2\"/><path d=\"M18 22l10-5 10 5-10 5z\"/><path d=\"M22 24v5c2 2 10 2 12 0v-5M38 22v6\"/></svg>\n</div>\n<div class=\"abs mtxt\"><div class=\"a\">MODALIDAD:</div><div class=\"b\">ASINCRÓNICA</div></div>\n\n<div class=\"abs dir\" id=\"dir\"></div>\n<div class=\"abs lin\"></div>\n\n<script>\n  const d = JSON.parse(document.getElementById('datos').textContent);\n  const esc = s => String(s == null ? '' : s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const $ = id => document.getElementById(id);\n  $('logo').src = d.logo_adipa;\n\n  // Título: con \":\" → lo de antes (incluidos los \":\") va arriba en morado y lo de después en recuadros.\n  // Sin \":\" → arriba \"Especialización en\" y el resto del nombre (sin \"Especialización de/en\") en recuadros\n  const nombre = String(d.nombre_programa || '').trim(), k = nombre.indexOf(':');\n  let pre, dest;\n  if (k >= 0) { pre = nombre.slice(0, k + 1); dest = nombre.slice(k + 1).trim(); }\n  else { const m = nombre.match(/^especializaci[oó]n\\s+(de|en)\\s+/i); pre = m ? m[0].trim() : 'Especialización en'; dest = nombre.slice(m ? m[0].length : 0).trim(); }\n  $('pre').textContent = pre;\n  $('dest').innerHTML = `<span>${esc(dest)}</span>`;\n\n  // ¿Qué aprenderás? (la IA los resume desde [objetivos_especificos]; máx. 2)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 2).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Director(a): títulos en una línea (regular) y nombre en negrita\n  const doc = d.docente || {};\n  const nomDoc = String(doc.nombre || '').trim();\n  const titulos = (nomDoc.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)/) || [''])[0];\n  const soloNombre = nomDoc.slice(titulos.length).trim();\n  $('dir').innerHTML = (titulos ? `<div class=\"tt\">${esc(titulos.trim())}</div>` : '') + `<div class=\"nn\" id=\"dir-nn\">${esc(soloNombre || nomDoc)}</div>`;\n\n  // Foto: retrato de busto (cabeza y pecho), centrado por la cabeza\n  const recortar = src => new Promise(res => {\n    if (!src) return res(null);\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5, cab: 0.45 });\n        const w = x1 - x0 + 1, h = Math.min(y1 - y0 + 1, Math.round(w * 1.25));\n        let sx = 0, n = 0, cab = 0;\n        for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        for (let y = y0; y < y0 + h * 0.25; y++) { let a = -1, b = -1; for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { if (a < 0) a = x; b = x; } if (b - a > cab) cab = b - a; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5, cab: cab / w });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5, cab: 0.45 }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título: arriba (190) la parte morada y debajo los recuadros; la letra baja hasta que todo cabe antes de 540\n    const pr = $('pre'), de = $('dest'); let fs = 58;\n    const poner = () => {\n      const fp = Math.round(fs * 0.76);\n      pr.style.fontSize = fp + 'px'; pr.style.lineHeight = Math.round(fp * 1.22) + 'px'; pr.style.top = '186px';\n      de.style.fontSize = fs + 'px'; de.style.lineHeight = Math.round(fs * 1.48) + 'px'; de.style.top = (190 + pr.offsetHeight + 22) + 'px';\n    };\n    poner(); while (190 + pr.offsetHeight + 22 + de.offsetHeight > 552 && fs > 26) { fs -= 1; poner(); }\n    const finT = 190 + pr.offsetHeight + 22 + de.offsetHeight;\n    // ¿Qué aprenderás? desde el título hasta la modalidad (1005); la letra se adapta al espacio\n    const top = Math.max(560, finT + 40);\n    $('barra').style.top = top + 'px'; $('barra').style.height = (1005 - top) + 'px';\n    $('que').style.top = (top + 8) + 'px';\n    const ap = $('aprend'), apTop = top + 78; ap.style.top = apTop + 'px';\n    let fa = 30;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.25) + 'px'; ap.style.gap = Math.round(fa * 1.4) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.25 - 58) / 2 + 2) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > 995 - apTop && fa > 14) { fa -= 0.5; ponerA(); }\n    // Nombre del director(a): la letra baja si no cabe (1 línea hasta 28; si es más largo, 2 líneas)\n    const nn = $('dir-nn'); let fn = 34;\n    const ponerN = () => { nn.style.fontSize = fn + 'px'; nn.style.lineHeight = Math.round(fn * 1.2) + 'px'; };\n    ponerN(); while (nn.offsetHeight > Math.round(fn * 1.2) + 1 && fn > 28) { fn -= 1; ponerN(); }\n    while (nn.offsetHeight > Math.round(fn * 1.2) * 2 + 1 && fn > 20) { fn -= 1; ponerN(); }\n  };\n\n  Promise.all([document.fonts.ready, recortar(doc.foto)]).then(([, f]) => {\n    // Cabeza centrada en x = 950; la foto parte en y = 330 (la cabeza puede salir del círculo, como en el diseño) y baja hasta el borde del círculo\n    if (f) {\n      const alto = 720;\n      const w = Math.round(alto * f.w / f.h);\n      $('foto').innerHTML = `<img src=\"${f.src}\" style=\"position:absolute;top:330px;height:${alto}px;width:${w}px;left:${Math.round(950 - f.cx * w)}px\">`;\n    }\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1200, "h": 1200}, "acreditacion": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1200X1200-RRSS-V2 — Acreditación</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --morado: #7051F8; --morado-txt: #6F51F2; --cian: #2FB5FC; --linea: #25B6F6; --navy: #182341; --lila: #EFF1FC; --celeste: #CAE8FF; --a