aprend\"></div>\n<div class=\"abs certif\" id=\"certif\"></div>\n\n<div class=\"abs circulo\"></div>\n<div class=\"abs foto\" id=\"foto\"></div>\n<div class=\"abs doc\" id=\"doc\"></div>\n\n<script>\n  const d = JSON.parse(document.getElementById('datos').textContent);\n  const esc = s => String(s == null ? '' : s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const $ = id => document.getElementById(id);\n  $('logo').src = d.logo_adipa;\n\n  // Viñeta y título (igual que la versión 1): \"Acreditación Oficial [Clínica] [Internacional] <título>\" → la primera parte va a la viñeta\n  const nombre = String(d.nombre_programa || '').trim();\n  const m = nombre.match(/^(acreditaci[oó]n\\s+oficial(?:\\s+(?:cl[ií]nica|internacional))*)\\s+(.+)$/i);\n  $('vineta').textContent = m ? m[1] : 'Acreditación Oficial';\n  const t0 = (m ? m[2] : nombre).replace(/^(en|de)\\s+/i, '');\n  const titulo = t0.charAt(0).toUpperCase() + t0.slice(1);\n  $('titulo').textContent = titulo;\n  // Frase final (\"Certifícate en el uso clínico del Instrumento …\"): por ahora la agrega diseño a mano (20 oct). Se deja el espacio libre abajo\n  $('certif').innerHTML = '';\n\n  // Fecha: \"Sábado 14 de noviembre de 2026\" o \"2026-11-14\" → \"Noviembre 2026\"\n  const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];\n  const f = String(d.fecha_inicio || '').toLowerCase(), iso = f.match(/(\\d{4})-(\\d{2})-\\d{2}/);\n  let mes = -1, anio = '';\n  if (iso) { anio = iso[1]; mes = +iso[2] - 1; } else { mes = MESES.findIndex(x => f.includes(x)); anio = (f.match(/\\b(20\\d{2})\\b/) || [])[1] || ''; }\n  $('mes').textContent = mes < 0 ? '' : `${MESES[mes][0].toUpperCase() + MESES[mes].slice(1)} ${anio}`.trim();\n\n  // ¿Qué aprenderás? (la IA los resume desde [objetivos_especificos]; máx. 3)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 3).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Docente: títulos en una línea y nombre debajo, con línea amarilla\n  const doc = d.docente || {};\n  const nomDoc = String(doc.nombre || '').trim();\n  const titulos = (nomDoc.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)/) || [''])[0];\n  const soloNombre = nomDoc.slice(titulos.length).trim();\n  $('doc').innerHTML = (titulos ? `<div class=\"tt\" id=\"doc-tt\">${esc(titulos.trim())}</div>` : '') + `<div class=\"nn\" id=\"doc-nn\">${esc(soloNombre || nomDoc)}</div><div class=\"lin\"></div>`;\n\n  // Foto: retrato de busto (cabeza y pecho), centrado por la cabeza\n  const recortar = src => new Promise(res => {\n    if (!src) return res(null);\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 });\n        const w = x1 - x0 + 1, h = Math.min(y1 - y0 + 1, Math.round(w * 1.25));\n        let sx = 0, n = 0;\n        for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5 });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título grande (desde 320): la letra baja hasta que cabe en 2 líneas y en el ancho\n    const tit = $('titulo'); let fs = 124;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.08) + 'px'; };\n    ponerT(); while ((tit.offsetHeight > Math.round(fs * 1.08) * 2 + 1 || tit.scrollWidth > tit.clientWidth + 1 || tit.offsetHeight > 170) && fs > 40) { fs -= 2; ponerT(); }\n    tit.style.top = (318 + Math.max(0, (150 - tit.offsetHeight) / 2)) + 'px';\n    const finT = Math.max(468, 318 + tit.offsetHeight);\n    $('fecha').style.top = (finT + 18) + 'px';\n    $('que').style.top = (finT + 96) + 'px';\n    $('subr').style.top = (finT + 156) + 'px';\n    // Espacio reservado para la frase final de diseño: 2 líneas (1010–1090)\n    // Aprendizajes: entre la línea celeste y la frase final; la letra se adapta al espacio\n    const ap = $('aprend'), apTop = finT + 200, apFin = 970;\n    ap.style.top = apTop + 'px';\n    let fa = 28;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.15) + 'px'; ap.style.gap = Math.round(fa * 1.0) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.15 - 44) / 2) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > apFin - apTop && fa > 14) { fa -= 0.5; ponerA(); }\n    // Docente: letra 22; baja si el nombre no cabe en 2 líneas\n    let fn = 23; const tt = $('doc-tt'), nn = $('doc-nn');\n    const ponerN = () => { [tt, nn].forEach(e => { if (e) { e.style.fontSize = fn + 'px'; e.style.lineHeight = Math.round(fn * 1.3) + 'px'; } }); };\n    ponerN(); while (nn.offsetHeight > Math.round(fn * 1.3) * 2 + 1 && fn > 16) { fn -= 1; ponerN(); }\n  };\n\n  Promise.all([document.fonts.ready, recortar(doc.foto)]).then(([, f]) => {\n    // Cabeza centrada en x = 920; la foto parte en y = 360 (puede salir del círculo arriba) y baja hasta el borde del círculo\n    if (f) {\n      const alto = 640, w = Math.round(alto * f.w / f.h);\n      $('foto').innerHTML = `<img src=\"${f.src}\" style=\"position:absolute;top:360px;height:${alto}px;width:${w}px;left:${Math.round(920 - f.cx * w)}px\">`;\n    }\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1200, "h": 1200}, "sesion": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1200X1200-RRSS-V2 — Sesión Magistral</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --azul: #0A1E41; --morado: #6F4FFB; --cian: #2EB6FF; --morado-txt: #6F51F2; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1200px; height: 1200px; overflow: hidden; }\n  body { font-family: 'Poppins', sans-serif; background: var(--azul); position: relative; color: #fff; }\n  .abs { position: absolute; }\n  .capa { left: 0; top: 0; width: 1200px; height: 1200px; }\n  b { font-weight: 700; }\n\n  .logos { left: 42px; top: 77px; width: 565px; height: 83px; border-radius: 18px; background: #F4F4FB; display: flex; align-items: center; justify-content: center; gap: 24px; }\n  .logos .logo-adipa { height: 46px; mix-blend-mode: multiply; } .logos .sep { width: 2px; height: 54px; background: #0A1E41; } .logos .logo-psy { height: 32px; }\n  .vineta { left: 38px; top: 226px; height: 56px; padding: 0 20px; border-radius: 28px; border: 2px solid #B7A6FF; background: var(--morado); font-weight: 700; font-size: 34px; line-height: 54px; white-space: nowrap; }\n  .titulo { left: 75px; width: 540px; font-weight: 400; }\n  .pill-mod { left: 62px; height: 48px; padding: 0 24px 0 10px; border-radius: 24px; background: var(--cian); display: flex; align-item