\n  // ¿Qué aprenderás? (la IA los resume desde [objetivos_especificos]; máx. 3)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 3).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Docentes (máx. 3): bandera de su país; títulos en la primera línea y nombre debajo\n  const partesDoc = n => { n = String(n).trim(); const m = n.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)(.+)$/); return m ? [m[1].trim(), m[2].trim()] : null; };\n  const docs = (d.docentes || []).filter(x => x.nombre && x.nombre.trim()).slice(0, 3);\n  $('docentes').innerHTML = docs.map(x => { const p = partesDoc(x.nombre);\n    return `<div class=\"docente\">${x.bandera ? `<img class=\"bandera\" src=\"${esc(x.bandera)}\" alt=\"\">` : ''}<div class=\"nombre\">${p ? `${esc(p[0])}<br><span class=\"nom\">${esc(p[1])}</span>` : esc(x.nombre.trim())}</div></div>`; }).join('');\n  // Si el nombre no cabe en una línea, el primer nombre sube con los títulos (\"PhD. Mg. Ps. John / Sommers-Flanagan\"), igual que la versión 1\n  const ajustarNombres = () => document.querySelectorAll('#docentes .nombre').forEach((el, i) => {\n    const nom = el.querySelector('.nom'); if (!nom) return;\n    const lh = parseFloat(getComputedStyle(el).lineHeight);\n    if (nom.getBoundingClientRect().height > lh * 1.5) {\n      const p = partesDoc(docs[i].nombre), k = p[1].indexOf(' ');\n      if (k > 0) el.innerHTML = `${esc(p[0])} ${esc(p[1].slice(0, k))}<br>${esc(p[1].slice(k + 1))}`;\n    }\n  });\n\n  // Fotos (1200X1200-POPUP, sin fondo): se recortan los márgenes transparentes\n  const recortar = src => new Promise(res => {\n    if (!src) return res('');\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res(src);\n        const o = document.createElement('canvas'); o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;\n        o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);\n        res(o.toDataURL('image/png'));\n      } catch (e) { res(src); }\n    };\n    im.onerror = () => res(src);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título (305–500): la letra parte en 40 y baja hasta que cabe\n    const tit = $('titulo'); let fs = 40;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.22) + 'px'; };\n    ponerT(); while (tit.offsetHeight > 195 && fs > 24) { fs -= 1; ponerT(); }\n    tit.style.top = '305px';\n    const finT = 305 + tit.offsetHeight;\n    $('mod').style.top = (finT + 24) + 'px';\n    // ¿Qué aprenderás? desde la modalidad hasta abajo (1095); la letra se adapta al espacio\n    const top = finT + 100;\n    $('barra').style.top = top + 'px'; $('barra').style.height = (1095 - top) + 'px';\n    $('que').style.top = (top + 6) + 'px';\n    const ap = $('aprend'), apTop = top + 82; ap.style.top = apTop + 'px';\n    let fa = 26;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.22) + 'px'; ap.style.gap = Math.round(fa * 1.3) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.22 - 58) / 2 + 4) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > 1085 - apTop && fa > 14) { fa -= 0.5; ponerA(); }\n    // Nombres de docentes: letra 25 (3 docentes: más chica); baja si un nombre ocupa más de 3 líneas\n    let fn = docs.length > 2 ? 21 : 25;\n    const noms = [...document.querySelectorAll('#docentes .nombre')];\n    const ponerN = () => noms.forEach(n => { n.style.fontSize = fn + 'px'; n.style.lineHeight = Math.round(fn * 1.25) + 'px'; });\n    ponerN(); ajustarNombres();\n    const maxL = docs.length > 2 ? 4 : 3;   // con 3 docentes se permite una línea más\n    while (noms.some(n => n.offsetHeight > Math.round(fn * 1.25) * maxL + 1) && fn > 18) { fn -= 1; ponerN(); }\n  };\n\n  Promise.all([document.fonts.ready, recortar(d.fotos)]).then(([, fotos]) => {\n    if (fotos) $('fotos').src = fotos;\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1200, "h": 1200}};
