))}</div>`).join('')}`\n    : `<div class=\"nom\">${esc((docs[0] || {}).nombre || '')}</div><div class=\"rol\">Docente</div>`;\n\n  // Foto del docente como retrato de busto (cabeza y pecho), aunque la _SF_ sea de cuerpo entero:\n  // se recortan los márgenes transparentes y la altura se limita a ~1,25 veces el ancho de los hombros\n  const recortar = src => new Promise(res => {\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight });\n        const w = x1 - x0 + 1, h = Math.min(y1 - y0 + 1, Math.round(w * 1.25));\n        // centro de la cabeza: promedio horizontal de la silueta en el 18 % superior\n        let sx = 0, n = 0;\n        for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5 });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  // ¿Algún texto invade el círculo celeste? (centro 940,1580; radio 390 + 24 px de margen)\n  const chocaCirculo = el => {\n    const r = document.createRange(); r.selectNodeContents(el);\n    return [...r.getClientRects()].some(q => {\n      const cx = Math.max(q.left, Math.min(940, q.right)), cy = Math.max(q.top, Math.min(1580, q.bottom));\n      return Math.hypot(cx - 940, cy - 1580) < 414;\n    });\n  };\n  // Bloque izquierdo, en 3 zonas que no se pisan:\n  //  1) Título: letra de 54 px que baja solo si no cabe en 4 líneas o toca el círculo.\n  //  2) Fecha y horas: ancladas abajo (suben si hay más países).\n  //  3) ¿Qué aprenderás?: ocupa todo el espacio entre el título y la fecha; la letra crece o se achica para llenarlo.\n  //  La línea celeste va desde \"¿Qué aprenderás?\" hasta la fecha.\n  const ajustar = () => {\n    // Píldora \"Gratuito\" pegada a la de \"Seminario Online\" (se mide con la fuente ya cargada)\n    const ps = $('pill-sem'); $('pill-gra').style.left = (ps.offsetLeft + ps.offsetWidth - 42) + 'px';\n    const tit = $('titulo'), ap = $('aprend');\n    let fs = 60;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.2) + 'px'; };\n    ponerT();\n    while ((tit.offsetHeight > Math.round(fs * 1.2) * 4 + 2 || chocaCirculo(tit)) && fs > 40) { fs -= 1; ponerT(); }\n\n    // Fecha y horas, ancladas abajo\n    // Historia: termina en 1540 (zona segura de Meta)\n    const varios = paises.length > 1, altoHoras = varios ? paises.length * 38 : 50;\n    $('horas').style.fontSize = (varios ? 27 : 44) + 'px';\n    $('horas').style.lineHeight = (varios ? 38 : 50) + 'px';\n    const caja = $('caja'); caja.style.top = (1845 - caja.offsetHeight) + 'px';\n    const yHoras = 1540 - altoHoras, yFecha = yHoras - 18 - 3 - 14 - 64;\n    $('fecha').style.top = yFecha + 'px';\n    $('subraya').style.top = (yFecha + 64 + 14) + 'px';\n    $('horas').style.top = yHoras + 'px';\n\n    // ¿Qué aprenderás?\n    const yQue = tit.offsetTop + tit.offsetHeight + 36;\n    $('que').style.top = yQue + 'px';\n    const apTop = yQue + 62, apMax = yFecha - 34;\n    ap.style.top = apTop + 'px';\n    let fa = 32;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.3) + 'px'; ap.style.gap = Math.round(fa * 1.1) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.3 - 38) / 2) + 'px');\n    };\n    ponerA();\n    while ((apTop + ap.offsetHeight > apMax || chocaCirculo(ap)) && fa > 15) { fa -= 0.5; ponerA(); }\n\n    // Línea celeste: desde \"¿Qué aprenderás?\" hasta la fecha\n    $('barra').style.top = (yQue - 14) + 'px';\n    $('barra').style.height = (yFecha - 6 - (yQue - 14)) + 'px';\n    // Caja amarilla: más alta si son 2 docentes\n  };\n\n  Promise.all([document.fonts.ready, ...docs.map(x => recortar(x.foto))]).then(([, ...fotos]) => {\n    fotos = fotos.filter(Boolean);\n    // Historia: retratos apoyados abajo, ubicados por el centro de la cabeza: 1 docente → x = 880;\n    // 2 docentes → x = 760 y 960, un poco más chicos (el primero adelante)\n    const alto = fotos.length > 1 ? 600 : 720, centros = fotos.length > 1 ? [760, 960] : [880];\n    $('fotos').innerHTML = fotos.map((f, i) => { const w = Math.round(alto * f.w / f.h); return `<img src=\"${f.src}\" style=\"position:absolute;bottom:0;height:${alto}px;width:${w}px;left:${Math.round(centros[i] - f.cx * w)}px;z-index:${fotos.length - i}\">`; }).join('');\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1080, "h": 1920}, "curso_CS": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1080X1920-RRSS-V2 — Curso Sincrónico (historia)</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --morado: #6F51F2; --morado-osc: #402AB4; --cian: #2FB5FC; --linea: #25B6F6; --oscuro: #0A1C42; --fondo: #E5F3FF; --circ: #D3EAFB; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1080px; height: 1920px; overflow: hidden; }\n  /* Zona segura de Meta para historias: textos entre x 62–1018 e y 269–1546 */\n  body { font-family: 'Poppins', sans-serif; background: var(--fondo); position: relative; color: var(--oscuro); }\n  .abs { position: absolute; }\n  b { font-weight: 700; }\n  .circ { border-radius: 50%; background: var(--circ); }\n\n  /* Escuela(s) arriba a la derecha, más arriba que el logo ADIPA (como el diseño) */\n  .logo { left: 80px; top: 380px; height: 62px; display: block; }\n\n  /* Escuela(s): \"A\" en recuadro blanco + nombre(s) de la Escuela (mismo recurso que la V1) */\n  .escuelas { right: 62px; top: 270px; height: 88px; display: flex; align-items: center; gap: 20px; }\n  .escuela { position: relative; height: 88px; overflow: hidden; flex: none; }\n  .escuela img { height: 88px; display: block; }\n  .escuela.primera::before { content: ''; position: absolute; left: 0; top: 4px; width: 80px; height: 80px; border-radius: 13px; background: #fff; }\n  .escuela.primera img { position: relative; }\n  .escuela.segunda img { margin-left: -101px; }\n  .sep { width: 2px; height: 78px; background: #7d8db0; opacity: .6; }\n\n  .vineta { left: 62px; top: 458px; height: 64px; padding: 0 18px; border-radius: 18px; background: var(--cian); color: #fff; font-weight: 700; font-size: 34px; line-height: 66px; white-space: nowrap; }\n  .titulo { left: 80px; width: 920px; color: #000; font-weight: 400; }\n\n  /* Foto del docente (busto, sin fondo) a la derecha */\n  .fotos { left: 0; top: 0; width: 1080px; height: 1920px; z-index: 3; }  /* sobre la tarjeta blanca, bajo los textos */\n\n  /* Tarjeta blanca: ¿Qué aprenderás? */\n  .tarjeta { left: 62px; top: 750px; width: 720px; height: 420px; border-radius: 45px; background: #fff; z-index: 2; }\n  .barra { left: 137px; top: 776px; width: 10px; height: 370px; z-index: 4; border-radius: 5px; background: var(--linea); }\n  .que { left: 192px; top: 780px; z-index: 4; color: var(--morado); font-weight: 700; font-size: 40px; line-height: 50px; }\n  .aprend { left: 192px; top: 852px; width: 470px; display: flex; flex-direction: column; z-index: 4; }\n  .aprend .item { position: relative; color: var(--oscuro); font-weight: 400; text-align: justify; }\n  .aprend .check { position: absolute; left: -80px; top: 0; width: 56px; height: 56px; border-radius: 50%; background: #fff; border: 2px solid var(--morado); display: flex; align-items: center; justify-content: center; }\n  .aprend .check svg { width: 36px; height: 36px; }\n\n  /* Fecha */\n  .vivo { left: 84px; top: 1192px; height: 48px; padding: 0 18px; border-radius: 16px; background: var(--cian); color: #fff; font-weight: 700; font-size: 30px; line-height: 50px; z-index: 5; white-space: nowrap; }\n  .fecha { left: 62px; top: 1222px; width: 560px; height: 142px; border-radius: 36px; z-index: 4; background: var(--morado); display: flex; align-items: center; color: #fff; }\n  .fecha svg { width: 72px; height: 72px; margin-left: 44px; flex: none; }\n  .fecha .sep2 { width: 2px; height: 100px; background: rgba(255,255,255,.7); margin: 0 22px 0 32px; }\n  .fecha .n { font-size: 84px; line-height: 84px; font-weight: 700; margin-right: 14px; }\n  .fecha .m { font-size: 40px; line-height: 44px; font-weight: 700; } .fecha .a { font-size: 38px; line-height: 42px; font-weight: 400; }\n\n  /* Docente(s) */\n  /* Docente(s): a la derecha como el diseño; ~100 px más abajo que el límite de la zona segura (pedido 20 oct) */\n  .doc { left: 430px; bottom: 270px; width: 588px; min-height: 150px; border-radius: 32px; background: #fff; display: flex; align-items: center; padding: 18px 26px 18px 38px; gap: 22px; z-index: 5; }\n  .doc .ico { width: 96px; height: 96px; border-radius: 50%; background: #D9EEFF; display: flex; align-items: center; justify-content: center; flex: none; }\n  .doc .ico svg { width: 60px; height: 60px; }\n  .doc .lbl { color: var(--morado-osc); font-weight: 700; font-size: 22px; line-height: 30px; }\n  .doc .nom { color: var(--morado); font-weight: 700; font-size: 32px; line-height: 38px; }\n  .doc.dos .nom { font-size: 26px; line-height: 32px; }\n</style>\n</head>\n<body>\n\n<!-- ===== DATOS: n8n reemplaza este bloque con los datos del programa ===== -->\n<script id=\"datos\" type=\"application/json\">__DATOS__</script>\n<!-- ======================================================================= -->\n\n<div class=\"abs circ\" style=\"left:420px;top:-420px;width:1200px;height:1200px\"></div>\n<div class=\"abs circ\" style=\"left:-320px;top:1320px;width:760px;height:760px\"></div>\n<div class=\"abs fotos\" id=\"fotos\"></div>\n\n<img class=\"abs logo\" id=\"logo\" alt=\"\">\n<div class=\"abs escuelas\" id=\"escuelas\"></div>\n<div class=\"abs vineta\">CURSO CERTIFICADO</div>\n<div class=\"abs titulo\" id=\"titulo\"></div>\n\n<div class=\"abs tarjeta\"></div>\n<div class=\"abs barra\"></div>\n<div class=\"abs que\">¿Qué aprenderás?</div>\n<div class=\"abs aprend\" id=\"aprend\"></div>\n\n<div class=\"abs vivo\">¡Interacción en vivo!</div>\n<div class=\"abs fecha\">\n  <svg viewBox=\"0 0 64 64\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><rect x=\"6\" y=\"12\" width=\"52\" height=\"46\" rx=\"6\"/><path d=\"M6 24h52M18 6v12M46 6v12\"/><rect x=\"17\" y=\"34\" width=\"30\" height=\"12\" rx=\"2\"/><path d=\"M27 34v12M37 34v12\"/></svg>\n  <div class=\"sep2\"></div>\n  <span class=\"n\" id=\"dia\"></span>\n  <div><div class=\"m\" id=\"mes\"></div><div class=\"a\" id=\"anio\"></div></div>\n</div>\n\n<div class=\"abs doc\" id=\"doc\">\n  <div class=\"ico\"><svg viewBox=\"0 0 64 64\" fill=\"none\" stroke=\"#0E2245\" stroke-width=\"2.6\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><rect x=\"6\" y=\"10\" width=\"52\" height=\"34\" rx=\"3\"/><path d=\"M24 54h16M32 44v10\"/><circle cx=\"32\" cy=\"22\" r=\"5\"/><path d=\"M23 38c1-5 5-8 9-8s8 3 9 8\"/><path d=\"M12 16h8M12 21h6\"/></svg></div>\n  <div id=\"doc-txt\"></div>\n</div>\n\n<script>\n  const d = JSON.parse(document.getElementById('datos').textContent);\n  const esc = s => String(s == null ? '' : s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const $ = id => document.getElementById(id);\n  const MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];\n  $('logo').src = d.logo_adipa;\n\n  // Escuela(s): la primera con la \"A\" en recuadro blanco; la segunda solo el nombre, separadas por una línea\n  const escs = (d.escuelas || []).filter(Boolean).slice(0, 2);\n  $('escuelas').innerHTML = escs.map((src, i) => `${i ? '<div class=\"sep\"></div>' : ''}<div class=\"escuela ${i ? 'segunda' : 'primera'}\"><img src=\"${esc(src)}\" alt=\"\"></div>`).join('');\n\n  // Título: negrita hasta los \":\" (incluidos); sin \":\" todo en negrita\n  const t = String(d.nombre_programa || '').trim(), k = t.indexOf(':');\n  $('titulo').innerHTML = k < 0 ? `<b>${esc(t)}</b>` : `<b>${esc(t.slice(0, k + 1))}</b> ${esc(t.slice(k + 1).trim())}`;\n\n  // Fecha \"2026-09-22 21:00\" → \"22 / Septiembre / 2026\"\n  const [Y, M, D] = String(d.fecha_inicio || '').split(/[ T]/)[0].split('-').map(Number);\n  $('dia').textContent = String(D || '').padStart(2, '0'); $('mes').textContent = MESES[(M || 1) - 1]; $('anio').textContent = Y || '';\n\n  // ¿Qué aprenderás? (los genera la IA desde [objetivos_especificos]; máx. 2)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 2).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Docente(s), máx. 2\n  const docs = (d.docentes || []).filter(x => x.nombre && x.nombre.trim()).slice(0, 2);\n  if (docs.length > 1) $('doc').classList.add('dos');\n  $('doc-txt').innerHTML = `<div class=\"lbl\">${docs.length > 1 ? 'Docentes' : 'Docente'}</div>` + docs.map(x => `<div class=\"nom\">${esc(x.nombre.trim())}</div>`).join('');\n\n  // Foto del docente como retrato de busto (cabeza y pecho), ubicada por el centro de la cabeza\n  const recortar = src => new Promise(res => {\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 });\n        // Historia: se entrega la silueta completa (alto real) para poder llevar la tarjeta al pecho; la cabeza se mide sobre el busto (1,25 × ancho)\n        const w = x1 - x0 + 1, h = y1 - y0 + 1, hb = Math.min(h, Math.round(w * 1.25));\n        let sx = 0, n = 0;\n        for (let y = y0; y < y0 + hb * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        // Ancho de la cabeza: fila más ancha del 25 % superior (sirve para igualar el tamaño de las caras con 2 docentes)\n        let cab = 0;\n        for (let y = y0; y < y0 + hb * 0.25; y++) { let a = -1, b = -1; for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { if (a < 0) a = x; b = x; } if (b - a > cab) cab = b - a; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5, cab: cab / w });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título entre la viñeta y la tarjeta (540–730): la letra baja hasta que cabe\n    const tit = $('titulo'); let fs = 54;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.2) + 'px'; };\n    ponerT(); while (tit.offsetHeight > 190 && fs > 32) { fs -= 1; ponerT(); }\n    tit.style.top = Math.round(540 + (190 - tit.offsetHeight) / 2) + 'px';\n    // Aprendizajes: llenan la tarjeta (852–1140); la letra crece o se achica según el espacio\n    const ap = $('aprend'); let fa = 30;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.32) + 'px'; ap.style.gap = Math.round(fa * 1.25) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.32 - 56) / 2) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > 288 && fa > 15) { fa -= 0.5; ponerA(); }\n  };\n\n  Promise.all([document.fonts.ready, ...docs.map(x => recortar(x.foto))]).then(([, ...fotos]) => {\n    fotos = fotos.filter(Boolean);\n    // Historia: 1 docente → busto grande (alto 1000, apoyado abajo; la cara queda sobre la tarjeta), cabeza en x = 880.\n    // 2 docentes: las caras se igualan por ancho de cabeza (fotos más abiertas o más cerradas quedan del mismo tamaño);\n    // el de la derecha va atrás y un poco más grande, el de la izquierda adelante, para que no se tapen las caras\n    const dos = fotos.length > 1;\n    const TEXTO_DER = 662;   // borde derecho del texto de \"¿Qué aprenderás?\"\n    const CAB = [260, 285], CENTRO = dos ? [745, 960] : [880];\n    // Busto: cada foto se escala por el ancho de la cabeza y se ubica para que la barbilla (≈ 1,4 × ancho de la cabeza\n    // bajo el borde superior) quede justo sobre la tarjeta del docente (y = 1474): la tarjeta queda a la altura del pecho.\n    // 1 docente: la cabeza puede salir sobre la tarjeta blanca; lo que caiga sobre el texto de \"¿Qué aprenderás?\" se oculta.\n    // 2 docentes: las fotos quedan bajo la tarjeta blanca (desde y = 1190), sin montarse sobre ella\n    const HW = dos ? [215, 235] : [330];\n    if (!dos) $('fotos').style.clipPath = `polygon(${TEXTO_DER + 24}px 0, 1080px 0, 1080px 1920px, 0 1920px, 0 1196px, ${TEXTO_DER + 24}px 1196px)`;\n    $('fotos').innerHTML = fotos.map((f, i) => {\n      const cab = (f.cab || 0.45) * f.w;\n      let s = HW[i] / cab, top = 1474 - 1.4 * HW[i] + (dos && i === 0 ? 30 : 0);\n      if (dos) top = Math.max(top, 1190);\n      if (top + f.h * s < 1920) { s = Math.max(s, 900 / f.h); top = 1920 - f.h * s; }   // foto corta: se apoya abajo\n      const alto = Math.round(f.h * s), w = Math.round(f.w * s);\n      let left = Math.round(CENTRO[i] - f.cx * w);\n      // La foto del extremo derecho llega hasta el borde (si la foto viene cortada, el corte no queda a la vista), moviendo la cabeza máx. 70 px\n      if (i === fotos.length - 1 && left + w < 1080) left += Math.min(70, 1080 - (left + w));\n      return `<img src=\"${f.src}\" style=\"position:absolute;top:${Math.round(top)}px;height:${alto}px;width:${w}px;left:${left}px;z-index:${dos ? (i ? 1 : 2) : 1}\">`;\n    }).join('');\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1080, "h": 1920}, "curso_CA": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1080X1920-RRSS-V2 — Curso Asincrónico (historia)</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --morado: #6F51F2; --morado-osc: #402AB4; --cian: #2FB5FC; --linea: #25B6F6; --oscuro: #0A1C42; --fondo: #F7EFF5; --circ: #FBF6FB; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1080px; height: 1920px; overflow: hidden; }\n  /* Zona segura de Meta para historias: textos entre x 62–1018 e y 269–1546 */\n  body { font-family: 'Poppins', sans-serif; background: var(--fondo); position: relative; color: var(--oscuro); }\n  .abs { position: absolute; }\n  b { font-weight: 700; }\n  .circ { border-radius: 50%; background: var(--circ); }\n\n  /* Escuela(s) arriba a la derecha, más arriba que el logo ADIPA (como el diseño) */\n  .logo { left: 80px; top: 380px; height: 62px; display: block; }\n\n  /* Escuela(s): \"A\" en recuadro blanco + nombre(s) de la Escuela (mismo recurso que la V1) */\n  .escuelas { right: 62px; top: 270px; height: 88px; display: flex; align-items: center; gap: 20px; }\n  .escuela { position: relative; height: 88px; overflow: hidden; flex: none; }\n  .escuela img { height: 88px; display: block; }\n  .escuela.primera::before { content: ''; position: absolute; left: 0; top: 4px; width: 80px; height: 80px; border-radius: 13px; background: #fff; }\n  .escuela.primera img { position: relative; }\n  .escuela.segunda img { margin-left: -101px; }\n  .sep { width: 2px; height: 78px; background: #7d8db0; opacity: .6; }\n\n  .vineta { left: 62px; top: 458px; height: 64px; padding: 0 18px; border-radius: 18px; background: var(--cian); color: #fff; font-weight: 700; font-size: 34px; line-height: 66px; white-space: nowrap; }\n  .titulo { left: 80px; width: 920px; color: #000; font-weight: 400; }\n\n  /* Foto del docente (busto, sin fondo) a la derecha */\n  .fotos { left: 0; top: 0; width: 1080px; height: 1920px; z-index: 3; }  /* sobre la tarjeta blanca, bajo los textos */\n\n  /* Tarjeta blanca: ¿Qué aprenderás? */\n  .tarjeta { left: 62px; top: 750px; width: 720px; height: 440px; border-radius: 45px; background: #fff; z-index: 2; }\n  .que { left: 114px; top: 780px; z-index: 4; color: var(--morado); font-weight: 700; font-size: 42px; line-height: 52px; }\n  .subr { left: 114px; top: 843px; width: 96px; height: 8px; border-radius: 4px; background: var(--linea); z-index: 4; }\n  .aprend { left: 125px; top: 880px; width: 590px; display: flex; flex-direction: column; z-index: 4; }\n  .aprend .item { position: relative; color: var(--oscuro); font-weight: 400; text-align: justify; }\n\n  /* Fecha */\n  .vivo { left: 84px; top: 1192px; height: 48px; padding: 0 18px; border-radius: 16px; background: var(--cian); color: #fff; font-weight: 700; font-size: 30px; line-height: 50px; z-index: 5; white-space: nowrap; }\n  .modal { left: 62px; top: 1222px; width: 500px; height: 142px; border-radius: 32px; z-index: 4; background: var(--morado); display: flex; align-items: center; color: #fff; }\n  .modal svg { width: 88px; height: 88px; margin-left: 40px; flex: none; }\n  .modal .sep2 { width: 2px; height: 100px; background: rgba(255,255,255,.7); margin: 0 24px 0 22px; }\n  .modal .m { font-size: 38px; line-height: 46px; font-weight: 400; } .modal .m b { font-weight: 700; }\n\n  /* Docente(s) */\n  /* Docente(s): a la derecha como el diseño; ~100 px más abajo que el límite de la zona segura (pedido 20 oct) */\n  .doc { left: 430px; bottom: 270px; width: 588px; min-height: 150px; border-radius: 32px; background: #fff; display: flex; align-items: center; padding: 18px 26px 18px 38px; gap: 22px; z-index: 5; }\n  .doc .ico { width: 96px; height: 96px; border-radius: 50%; background: #D9EEFF; display: flex; align-items: center; justify-content: center; flex: none; }\n  .doc .ico svg { width: 60px; height: 60px; }\n  .doc .lbl { color: var(--morado-osc); font-weight: 700; font-size: 22px; line-height: 30px; }\n  .doc .nom { color: var(--morado); font-weight: 700; font-size: 32px; line-height: 38px; }\n  .doc.dos .nom { font-size: 26px; line-height: 32px; }\n</style>\n</head>\n<body>\n\n<!-- ===== DATOS: n8n reemplaza este bloque con los datos del programa ===== -->\n<script id=\"datos\" type=\"application/json\">__DATOS__</script>\n<!-- ======================================================================= -->\n\n<div class=\"abs circ\" style=\"left:420px;top:-420px;width:1200px;height:1200px\"></div>\n<div class=\"abs circ\" style=\"left:-320px;top:1320px;width:760px;height:760px\"></div>\n<div class=\"abs fotos\" id=\"fotos\"></div>\n\n<img class=\"abs logo\" id=\"logo\" alt=\"\">\n<div class=\"abs escuelas\" id=\"escuelas\"></div>\n<div class=\"abs vineta\">CURSO CERTIFICADO</div>\n<div class=\"abs titulo\" id=\"titulo\"></div>\n\n<div class=\"abs tarjeta\"></div>\n<div class=\"abs que\">¿Qué aprenderás?</div>\n<div class=\"abs subr\"></div>\n<div class=\"abs aprend\" id=\"aprend\"></div>\n\n<div class=\"abs modal\">\n  <!-- Ícono provisorio: reemplazar por el original de diseño -->\n  <svg viewBox=\"0 0 64 64\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.6\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><rect x=\"4\" y=\"16\" width=\"44\" height=\"32\" rx=\"3\"/><path d=\"M18 56h16M26 48v8\"/><circle cx=\"26\" cy=\"29\" r=\"4.5\"/><path d=\"M18 42c1-5 4-7 8-7s7 2 8 7\"/><path d=\"M38 4h22v14H48l-5 5v-5h-5z\" fill=\"#6F51F2\"/><path d=\"M43 11h1M49 11h1M55 11h1\" stroke-width=\"3\"/></svg>\n  <div class=\"sep2\"></div>\n  <div class=\"m\">Modalidad<br><b>asincrónica</b></div>\n</div>\n<div class=\"abs vivo\">¡Estudia a tu ritmo!</div>\n\n<div class=\"abs doc\" id=\"doc\">\n  <div class=\"ico\"><svg viewBox=\"0 0 64 64\" fill=\"none\" stroke=\"#0E2245\" stroke-width=\"2.6\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><rect x=\"6\" y=\"10\" width=\"52\" height=\"34\" rx=\"3\"/><path d=\"M24 54h16M32 44v10\"/><circle cx=\"32\" cy=\"22\" r=\"5\"/><path d=\"M23 38c1-5 5-8 9-8s8 3 9 8\"/><path d=\"M12 16h8M12 21h6\"/></svg></div>\n  <div id=\"doc-txt\"></div>\n</div>\n\n<script>\n  const d = JSON.parse(document.getElementById('datos').textContent);\n  const esc = s => String(s == null ? '' : s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const $ = id => document.getElementById(id);\n  $('logo').src = d.logo_adipa;\n\n  // Escuela(s): la primera con la \"A\" en recuadro blanco; la segunda solo el nombre, separadas por una línea\n  const escs = (d.escuelas || []).filter(Boolean).slice(0, 2);\n  $('escuelas').innerHTML = escs.map((src, i) => `${i ? '<div class=\"sep\"></div>' : ''}<div class=\"escuela ${i ? 'segunda' : 'primera'}\"><img src=\"${esc(src)}\" alt=\"\"></div>`).join('');\n\n  // Título: negrita hasta los \":\" (incluidos); sin \":\" todo en negrita\n  const t = String(d.nombre_programa || '').trim(), k = t.indexOf(':');\n  $('titulo').innerHTML = k < 0 ? `<b>${esc(t)}</b>` : `<b>${esc(t.slice(0, k + 1))}</b> ${esc(t.slice(k + 1).trim())}`;\n\n  // ¿Qué aprenderás? (la IA lo resume desde [objetivo_general]; 1 solo aprendizaje)\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 1).map(a => `<div class=\"item\">${esc(a)}</div>`).join('');\n\n  // Docente(s), máx. 2\n  const docs = (d.docentes || []).filter(x => x.nombre && x.nombre.trim()).slice(0, 2);\n  if (docs.length > 1) $('doc').classList.add('dos');\n  $('doc-txt').innerHTML = `<div class=\"lbl\">${docs.length > 1 ? 'Docentes' : 'Docente'}</div>` + docs.map(x => `<div class=\"nom\">${esc(x.nombre.trim())}</div>`).join('');\n\n  // Foto del docente como retrato de busto (cabeza y pecho), ubicada por el centro de la cabeza\n  const recortar = src => new Promise(res => {\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 });\n        // Historia: se entrega la silueta completa (alto real) para poder llevar la tarjeta al pecho; la cabeza se mide sobre el busto (1,25 × ancho)\n        const w = x1 - x0 + 1, h = y1 - y0 + 1, hb = Math.min(h, Math.round(w * 1.25));\n        let sx = 0, n = 0;\n        for (let y = y0; y < y0 + hb * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        // Ancho de la cabeza: fila más ancha del 25 % superior (sirve para igualar el tamaño de las caras con 2 docentes)\n        let cab = 0;\n        for (let y = y0; y < y0 + hb * 0.25; y++) { let a = -1, b = -1; for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { if (a < 0) a = x; b = x; } if (b - a > cab) cab = b - a; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5, cab: cab / w });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título entre la viñeta y la tarjeta (540–730): la letra baja hasta que cabe\n    const tit = $('titulo'); let fs = 54;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.2) + 'px'; };\n    ponerT(); while (tit.offsetHeight > 190 && fs > 32) { fs -= 1; ponerT(); }\n    tit.style.top = Math.round(540 + (190 - tit.offsetHeight) / 2) + 'px';\n    // Aprendizaje: llena la tarjeta (880–1150); la letra se achica si no cabe (máx. 30)\n    const ap = $('aprend'); let fa = 30;\n    const ponerA = () => { ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.28) + 'px'; };\n    ponerA(); while (ap.offsetHeight > 250 && fa > 15) { fa -= 0.5; ponerA(); }\n    // Tarjeta blanca: se ajusta al largo del aprendizaje (no queda espacio vacío); máx. 440\n    document.querySelector('.tarjeta').style.height = Math.min(420, Math.max(240, 880 + ap.offsetHeight + 46 - 750)) + 'px';\n  };\n\n  Promise.all([document.fonts.ready, ...docs.map(x => recortar(x.foto))]).then(([, ...fotos]) => {\n    fotos = fotos.filter(Boolean);\n    // Historia: 1 docente → busto grande (alto 1000, apoyado abajo; la cara queda sobre la tarjeta), cabeza en x = 880.\n    // 2 docentes: las caras se igualan por ancho de cabeza (fotos más abiertas o más cerradas quedan del mismo tamaño);\n    // el de la derecha va atrás y un poco más grande, el de la izquierda adelante, para que no se tapen las caras\n    const dos = fotos.length > 1;\n    const TEXTO_DER = 715;   // borde derecho del texto de \"¿Qué aprenderás?\"\n    const CAB = [260, 285], CENTRO = dos ? [745, 960] : [880];\n    // Busto: cada foto se escala por el ancho de la cabeza y se ubica para que la barbilla (≈ 1,4 × ancho de la cabeza\n    // bajo el borde superior) quede justo sobre la tarjeta del docente (y = 1474): la tarjeta queda a la altura del pecho.\n    // 1 docente: la cabeza puede salir sobre la tarjeta blanca; lo que caiga sobre el texto de \"¿Qué aprenderás?\" se oculta.\n    // 2 docentes: las fotos quedan bajo la tarjeta blanca (desde y = 1190), sin montarse sobre ella\n    const HW = dos ? [215, 235] : [330];\n    if (!dos) $('fotos').style.clipPath = `polygon(${TEXTO_DER + 24}px 0, 1080px 0, 1080px 1920px, 0 1920px, 0 1196px, ${TEXTO_DER + 24}px 1196px)`;\n    $('fotos').innerHTML = fotos.map((f, i) => {\n      const cab = (f.cab || 0.45) * f.w;\n      let s = HW[i] / cab, top = 1474 - 1.4 * HW[i] + (dos && i === 0 ? 30 : 0);\n      if (dos) top = Math.max(top, 1190);\n      if (top + f.h * s < 1920) { s = Math.max(s, 900 / f.h); top = 1920 - f.h * s; }   // foto corta: se apoya abajo\n      const alto = Math.round(f.h * s), w = Math.round(f.w * s);\n      let left = Math.round(CENTRO[i] - f.cx * w);\n      // La foto del extremo derecho llega hasta el borde (si la foto viene cortada, el corte no queda a la vista), moviendo la cabeza máx. 70 px\n      if (i === fotos.length - 1 && left + w < 1080) left += Math.min(70, 1080 - (left + w));\n      return `<img src=\"${f.src}\" style=\"position:absolute;top:${Math.round(top)}px;height:${alto}px;width:${w}px;left:${left}px;z-index:${dos ? (i ? 1 : 2) : 1}\">`;\n    }).join('');\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1080, "h": 1920}, "diplomado": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1080X1920-RRSS-V2 — Diplomado (historia)</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --morado: #6F4FFB; --morado-txt: #6F51F2; --morado-osc: #402AB4; --cian: #2FB5FC; --linea: #25B6F6; --navy: #071B3E; --oscuro: #0A1C42; }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1080px; height: 1920px; overflow: hidden; }\n  /* Zona segura de Meta (historias): textos entre y 269 y ~1546; fecha y director quedan hasta ~100 px más abajo, como se aprobó en cursos */\n  body { font-family: 'Poppins', sans-serif; background: #fff; position: relative; color: var(--oscuro); }\n  .abs { position: absolute; }\n  b { font-weight: 700; }\n\n  .logo { left: 0; right: 0; margin: 0 auto; top: 280px; height: 74px; display: block; }\n\n  .vineta { left: 0; top: 392px; width: 450px; height: 84px; border-radius: 0 42px 42px 0; background: var(--cian); color: #fff; font-weight: 600; font-size: 48px; line-height: 86px; padding-left: 82px; white-space: nowrap; }\n  .titulo { left: 54px; width: 680px; color: var(--navy); font-weight: 400; }\n  .subr { left: 56px; width: 96px; height: 8px; border-radius: 4px; background: var(--morado-txt); }\n\n  /* ¿Qué aprenderás? */\n  .barra { left: 68px; width: 10px; border-radius: 5px; background: var(--linea); }\n  .que { left: 122px; color: var(--morado-txt); font-weight: 700; font-size: 44px; line-height: 54px; }\n  .aprend { left: 130px; width: 470px; display: flex; flex-direction: column; }\n  .aprend .item { position: relative; color: var(--oscuro); font-weight: 400; text-align: left; }  /* historia: alineado a la izquierda, como el diseño */\n  .aprend .check { position: absolute; left: -82px; top: 0; width: 60px; height: 60px; border-radius: 50%; background: #fff; border: 2px solid var(--morado-txt); display: flex; align-items: center; justify-content: center; }\n  .aprend .check svg { width: 40px; height: 40px; }\n\n  /* Fecha */\n  .fecha { left: 44px; top: 1490px; width: 606px; height: 160px; border-radius: 35px; background: var(--navy); display: flex; align-items: center; color: #fff; }\n  .fecha svg { width: 76px; height: 76px; margin-left: 36px; flex: none; }\n  .fecha .sep2 { width: 2px; height: 104px; background: rgba(255,255,255,.6); margin: 0 24px 0 28px; }\n  .fecha .n { font-size: 100px; line-height: 100px; font-weight: 700; margin-right: 16px; letter-spacing: -2px; }\n  .fecha .m { font-size: 42px; line-height: 48px; font-weight: 700; text-transform: uppercase; } .fecha .a { font-size: 42px; line-height: 48px; font-weight: 400; }\n  .deco { left: 40px; top: 1838px; width: 556px; height: 120px; border-radius: 40px; background: var(--morado); }\n\n  /* Panel morado + círculo con la foto del director(a) */\n  .panel { left: 755px; top: 312px; width: 325px; height: 1608px; border-radius: 75px 0 0 0; background: var(--morado); }\n  .panel2 { left: 685px; top: 1440px; width: 395px; height: 480px; border-radius: 0 0 0 110px; background: var(--morado); }\n  .circulo { left: 600px; top: 985px; width: 466px; height: 466px; border-radius: 50%; background: var(--cian); border: 5px solid #fff; }\n  /* La foto se recorta por el círculo, salvo arriba: la cabeza puede salir del círculo */\n  .foto { left: 0; top: 0; width: 1080px; height: 1920px; clip-path: path('M 600 0 H 1066 V 1218 H 600 Z M 600 1218 A 233 233 0 0 1 1066 1218 A 233 233 0 0 1 600 1218 Z'); }\n\n  /* Director(a) */\n  .dir { left: 685px; top: 1478px; width: 375px; height: 150px; border-radius: 0 40px 40px 0; background: #fff; display: flex; flex-direction: column; justify-cont