======================= -->\n\n<img class=\"abs logo\" id=\"logo\" alt=\"\">\n<div class=\"abs vineta\" id=\"vineta\"></div>\n<div class=\"abs tarjeta\"></div>\n<div class=\"abs pildora\"></div>\n<div class=\"abs barra-inf\"></div>\n\n<div class=\"abs titulo\" id=\"titulo\"></div>\n<div class=\"abs fecha\" id=\"fecha\"><svg viewBox=\"0 0 64 64\"><circle cx=\"32\" cy=\"32\" r=\"32\" fill=\"#2FB5FC\"/><g fill=\"none\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"17\" y=\"19\" width=\"30\" height=\"27\" rx=\"4\"/><path d=\"M17 27h30M24 15v7M40 15v7\"/><circle cx=\"40\" cy=\"40\" r=\"3\"/></g></svg><span id=\"mes\"></span></div>\n\n<div class=\"abs que\" id=\"que\">¿Qué aprenderás?</div>\n<div class=\"abs subr\" id=\"subr\"></div>\n<div class=\"abs aprend\" id=\"aprend\"></div>\n<div class=\"abs certif\" id=\"certif\"></div>\n\n<div class=\"abs circulo\"></div>\n<div class=\"abs foto\" id=\"foto\"></div>\n<div class=\"abs doc\" id=\"doc\"></div>\n\n<script>\n  const d = JSON.parse(document.getElementById('datos').textContent);\n  const esc = s => String(s == null ? '' : s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const $ = id => document.getElementById(id);\n  $('logo').src = d.logo_adipa;\n\n  // Viñeta y título (igual que la versión 1): \"Acreditación Oficial [Clínica] [Internacional] <título>\" → la primera parte va a la viñeta\n  const nombre = String(d.nombre_programa || '').trim();\n  const m = nombre.match(/^(acreditaci[oó]n\\s+oficial(?:\\s+(?:cl[ií]nica|internacional))*)\\s+(.+)$/i);\n  $('vineta').textContent = m ? m[1] : 'Acreditación Oficial';\n  const t0 = (m ? m[2] : nombre).replace(/^(en|de)\\s+/i, '');\n  const titulo = t0.charAt(0).toUpperCase() + t0.slice(1);\n  $('titulo').textContent = titulo;\n  // Frase final (\"Certifícate en el uso clínico del Instrumento …\"): por ahora la agrega diseño a mano (20 oct). Se deja el espacio libre abajo\n  $('certif').innerHTML = '';\n\n  // Fecha: \"Sábado 14 de noviembre de 2026\" o \"2026-11-14\" → \"Noviembre 2026\"\n  const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];\n  const f = String(d.fecha_inicio || '').toLowerCase(), iso = f.match(/(\\d{4})-(\\d{2})-\\d{2}/);\n  let mes = -1, anio = '';\n  if (iso) { anio = iso[1]; mes = +iso[2] - 1; } else { mes = MESES.findIndex(x => f.includes(x)); anio = (f.match(/\\b(20\\d{2})\\b/) || [])[1] || ''; }\n  $('mes').textContent = mes < 0 ? '' : `${MESES[mes][0].toUpperCase() + MESES[mes].slice(1)} ${anio}`.trim();\n\n  // ¿Qué aprenderás? (la IA los resume desde [objetivos_especificos]; máx. 3)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 3).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Docente: títulos en una línea y nombre debajo, con línea amarilla\n  const doc = d.docente || {};\n  const nomDoc = String(doc.nombre || '').trim();\n  const titulos = (nomDoc.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)/) || [''])[0];\n  const soloNombre = nomDoc.slice(titulos.length).trim();\n  $('doc').innerHTML = (titulos ? `<div class=\"tt\" id=\"doc-tt\">${esc(titulos.trim())}</div>` : '') + `<div class=\"nn\" id=\"doc-nn\">${esc(soloNombre || nomDoc)}</div><div class=\"lin\"></div>`;\n\n  // Foto: retrato de busto (cabeza y pecho), centrado por la cabeza\n  const recortar = src => new Promise(res => {\n    if (!src) return res(null);\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 });\n        const w = x1 - x0 + 1, h = Math.min(y1 - y0 + 1, Math.round(w * 1.25));\n        let sx = 0, n = 0;\n        for (let y = y0; y < y0 + h * 0.18; y++) for (let x = x0; x <= x1; x++) if (px[(y * c.width + x) * 4 + 3] > 10) { sx += x; n++; }\n        const o = document.createElement('canvas'); o.width = w; o.height = h;\n        o.getContext('2d').drawImage(c, x0, y0, w, h, 0, 0, w, h);\n        res({ src: o.toDataURL('image/png'), w, h, cx: n ? (sx / n - x0) / w : 0.5 });\n      } catch (e) { res({ src, w: im.naturalWidth, h: im.naturalHeight, cx: 0.5 }); }\n    };\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título grande (desde 540): la letra baja hasta que cabe en 2 líneas y en el ancho\n    const tit = $('titulo'); let fs = 150;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.08) + 'px'; };\n    ponerT(); while ((tit.offsetHeight > Math.round(fs * 1.08) * 2 + 1 || tit.scrollWidth > tit.clientWidth + 1 || tit.offsetHeight > 200) && fs > 44) { fs -= 2; ponerT(); }\n    tit.style.top = (540 + Math.max(0, (170 - tit.offsetHeight) / 2)) + 'px';\n    const finT = Math.max(710, 540 + tit.offsetHeight);\n    $('fecha').style.top = (finT + 20) + 'px';\n    $('que').style.top = (finT + 128) + 'px';\n    $('subr').style.top = (finT + 194) + 'px';\n    // Espacio reservado para la frase final de diseño a la izquierda de la foto: 2 líneas (~1300–1400)\n    // Aprendizajes: entre la línea celeste y la frase final; la letra se adapta al espacio\n    const ap = $('aprend'), apTop = finT + 240, apFin = 1280;\n    ap.style.top = apTop + 'px';\n    let fa = 32;\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.25) + 'px'; ap.style.gap = Math.round(fa * 1.2) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.25 - 56) / 2) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > apFin - apTop && fa > 14) { fa -= 0.5; ponerA(); }\n    // Docente: letra 22; baja si el nombre no cabe en 2 líneas\n    let fn = 28; const tt = $('doc-tt'), nn = $('doc-nn');\n    const ponerN = () => { [tt, nn].forEach(e => { if (e) { e.style.fontSize = fn + 'px'; e.style.lineHeight = Math.round(fn * 1.3) + 'px'; } }); };\n    ponerN(); while (nn.offsetHeight > Math.round(fn * 1.3) * 2 + 1 && fn > 16) { fn -= 1; ponerN(); }\n  };\n\n  Promise.all([document.fonts.ready, recortar(doc.foto)]).then(([, f]) => {\n    // Historia: cabeza centrada en x = 850; la foto parte en y = 1090 (puede salir del círculo arriba) y baja hasta el borde del círculo\n    if (f) {\n      const alto = 600, w = Math.round(alto * f.w / f.h);\n      $('foto').innerHTML = `<img src=\"${f.src}\" style=\"position:absolute;top:1090px;height:${alto}px;width:${w}px;left:${Math.round(850 - f.cx * w)}px\">`;\n    }\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1080, "h": 1920}, "sesion": {"html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<title>1080X1920-RRSS-V2 — Sesión Magistral (historia)</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=block\" rel=\"stylesheet\">\n<style>\n  :root { --azul: #0A1E41; --morado: #6F4FFC; --cian: #2EB6FF; --morado-txt: #6F51F2; }  /* colores muestreados del diseño */\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 1080px; height: 1920px; overflow: hidden; }\n  /* Diseño actualizado (20 oct): todo dentro de la zona segura de Meta (y 258–~1690) */\n  body { font-family: 'Poppins', sans-serif; background: var(--azul); position: relative; color: #fff; }\n  .abs { position: absolute; }\n  .capa { left: 0; top: 0; width: 1080px; height: 1920px; }\n  b { font-weight: 700; }\n\n  .logos { left: 64px; top: 258px; width: 565px; height: 84px; border-radius: 20px; background: #F4F4FB; display: flex; align-items: center; justify-content: center; gap: 24px; }\n  .logos .logo-adipa { height: 46px; mix-blend-mode: multiply; } .logos .sep { width: 2px; height: 54px; background: #6F4FFB; } .logos .logo-psy { height: 32px; }\n  .vineta { left: 86px; top: 422px; height: 66px; padding: 0 24px; border-radius: 33px; border: 2px solid #B7A6FF; background: var(--morado); font-weight: 700; font-size: 42px; line-height: 64px; white-space: nowrap; }\n  .titulo { left: 100px; width: 720px; font-weight: 400; }\n  .pill-mod { left: 88px; height: 56px; padding: 0 34px 0 12px; border-radius: 28px; background: var(--cian); display: flex; align-items: center; gap: 12px; font-size: 36px; white-space: nowrap; z-index: 3; }\n  .pill-mod svg { width: 38px; height: 38px; }\n\n  /* ¿Qué aprenderás? */\n  .barra { left: 100px; width: 10px; border-radius: 5px; background: var(--cian); }\n  .que { left: 128px; font-weight: 700; font-size: 44px; line-height: 54px; }\n  .aprend { left: 164px; width: 425px; z-index: 3; display: flex; flex-direction: column; }\n  .aprend .item { position: relative; font-weight: 400; text-align: justify; }\n  .aprend .check { position: absolute; left: -96px; top: 0; width: 66px; height: 66px; border-radius: 50%; background: #fff; display: flex; align-items: center; justify-content: center; }\n  .aprend .check svg { width: 48px; height: 48px; }\n\n  /* Docentes (máx. 3): bandera + títulos + nombre, con línea blanca a la izquierda */\n  .docentes { left: 105px; top: 1548px; width: 880px; display: flex; gap: 60px; }\n  .docentes.tres { width: 900px; gap: 26px; } .docentes.tres .docente { padding-left: 12px; } .docentes.tres .bandera { width: 52px; height: 31px; }\n  .docente { border-left: 6px solid #fff; padding-left: 16px; flex: 1 1 0; min-width: 0; }\n  .docente .bandera { display: block; width: 60px; height: 36px; object-fit: cover; margin-bottom: 10px; border: 1px solid rgba(255,255,255,.6); }\n  .docente .nombre { font-weight: 600; }\n  .fotos { object-fit: contain; object-position: center bottom; }\n</style>\n</head>\n<body>\n\n<!-- ===== DATOS: n8n reemplaza este bloque con los datos del programa ===== -->\n<script id=\"datos\" type=\"application/json\">__DATOS__</script>\n<!-- ======================================================================= -->\n\n<!-- Forma (diseño 20 oct, calcada del diseño): banda celeste inclinada (bordes superior e inferior paralelos, ~35°)\n     con el extremo izquierdo redondeado; detrás, dos bandas moradas paralelas que asoman arriba y abajo a la derecha -->\n<svg class=\"abs capa\" viewBox=\"0 0 1080 1920\">\n  <path d=\"M 1080 580 L 1000 636 L 940 678 L 920 694 L 905 712 L 896 730 L 890 748 L 887 766 L 886 785 L 886 800 L 900 789 L 1000 719 L 1080 663 Z\" fill=\"var(--morado)\"/>\n  <path d=\"M 900 1353 L 920 1349 L 940 1344 L 960 1337 L 980 1327 L 1000 1316 L 1040 1288 L 1080 1260 L 1080 1390 L 1060 1400 L 1040 1407 L 1020 1411 L 1000 1412 L 980 1409 L 960 1404 L 940 1394 L 920 1380 L 905 1364 Z\" fill=\"var(--morado)\"/>\n  <path d=\"M 1080 663 L 1000 719 L 900 789 L 800 859 L 700 930 L 680 952 L 660 980 L 645 1008 L 633 1040 L 625 1075 L 622 1110 L 625 1150 L 632 1180 L 640 1202 L 660 1239 L 680 1268 L 700 1289 L 720 1306 L 740 1321 L 760 1330 L 780 1338 L 800 1345 L 820 1351 L 840 1354 L 860 1355 L 880 1355 L 900 1353 L 920 1349 L 940 1344 L 960 1337 L 980 1327 L 1000 1316 L 1040 1288 L 1080 1260 Z\" fill=\"var(--cian)\"/>\n</svg>\n<!-- Fotos (1200X1200-POPUP) recortadas por la forma celeste, como en el diseño -->\n<div class=\"abs capa\" style=\"clip-path: path('M 1080 663 L 1000 719 L 900 789 L 800 859 L 700 930 L 680 952 L