`${esc(t.slice(0, k))} en <b>${esc(t.slice(k + 4).trim())}</b>`;\n    const c = t.indexOf(':');\n    return c > -1 ? `${esc(t.slice(0, c + 1))} <b>${esc(t.slice(c + 1).trim())}</b>` : `<b>${esc(t)}</b>`;\n  };\n  $('titulo').innerHTML = tituloSM(d.nombre_programa);\n\n  // ¿Qué aprenderás? (la IA los resume desde [objetivos_especificos]; máx. 3)\n  const check = '<svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"#6F51F2\" stroke-width=\"4.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 19l7 7 13-15\"/></svg>';\n  $('aprend').innerHTML = (d.aprendizajes || []).filter(Boolean).slice(0, 3).map(a => `<div class=\"item\"><span class=\"check\">${check}</span>${esc(a)}</div>`).join('');\n\n  // Docentes (máx. 3): bandera de su país; títulos en la primera línea y nombre debajo\n  const partesDoc = n => { n = String(n).trim(); const m = n.match(/^((?:[A-Za-zÁÉÍÓÚáéíóúÑñ()\\-]{1,8}\\.\\s*)+)(.+)$/); return m ? [m[1].trim(), m[2].trim()] : null; };\n  const docs = (d.docentes || []).filter(x => x.nombre && x.nombre.trim()).slice(0, 3);\n  $('docentes').innerHTML = docs.map(x => { const p = partesDoc(x.nombre);\n    return `<div class=\"docente\">${x.bandera ? `<img class=\"bandera\" src=\"${esc(x.bandera)}\" alt=\"\">` : ''}<div class=\"nombre\">${p ? `${esc(p[0])}<br><span class=\"nom\">${esc(p[1])}</span>` : esc(x.nombre.trim())}</div></div>`; }).join('');\n  // Si el nombre no cabe en una línea, el primer nombre sube con los títulos (\"PhD. Mg. Ps. John / Sommers-Flanagan\"), igual que la versión 1\n  const ajustarNombres = () => document.querySelectorAll('#docentes .nombre').forEach((el, i) => {\n    const nom = el.querySelector('.nom'); if (!nom) return;\n    const lh = parseFloat(getComputedStyle(el).lineHeight);\n    if (nom.getBoundingClientRect().height > lh * 1.5) {\n      const p = partesDoc(docs[i].nombre), k = p[1].indexOf(' ');\n      if (k > 0) el.innerHTML = `${esc(p[0])} ${esc(p[1].slice(0, k))}<br>${esc(p[1].slice(k + 1))}`;\n    }\n  });\n\n  // Fotos (1200X1200-POPUP, sin fondo): se recortan los márgenes transparentes\n  const recortar = src => new Promise(res => {\n    if (!src) return res('');\n    const im = new Image();\n    im.onload = () => {\n      try {\n        const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;\n        const g = c.getContext('2d'); g.drawImage(im, 0, 0);\n        const px = g.getImageData(0, 0, c.width, c.height).data;\n        let x0 = c.width, y0 = c.height, x1 = -1, y1 = -1;\n        for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++)\n          if (px[(y * c.width + x) * 4 + 3] > 10) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n        if (x1 < 0) return res(src);\n        const o = document.createElement('canvas'); o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;\n        o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);\n        res(o.toDataURL('image/png'));\n      } catch (e) { res(src); }\n    };\n    im.onerror = () => res(src);\n    im.src = src;\n  });\n\n  const ajustar = () => {\n    // Título (522–790): la letra parte en 50 y baja hasta que cabe\n    const tit = $('titulo'); let fs = 50;\n    const ponerT = () => { tit.style.fontSize = fs + 'px'; tit.style.lineHeight = Math.round(fs * 1.33) + 'px'; };\n    ponerT(); while (tit.offsetHeight > 268 && fs > 28) { fs -= 1; ponerT(); }\n    tit.style.top = '522px';\n    const finT = 522 + tit.offsetHeight;\n    $('mod').style.top = (finT + 52) + 'px';\n    // ¿Qué aprenderás? desde la modalidad hasta los docentes (1505); la letra se adapta al espacio\n    const top = finT + 155;\n    $('barra').style.top = top + 'px'; $('barra').style.height = (1505 - top) + 'px';\n    $('que').style.top = (top + 6) + 'px';\n    const ap = $('aprend'), apTop = top + 100; ap.style.top = apTop + 'px';\n    let fa = 30;   // máx. 30 px como el diseño; baja si no cabe\n    const ponerA = () => {\n      ap.style.fontSize = fa + 'px'; ap.style.lineHeight = Math.round(fa * 1.15) + 'px'; ap.style.gap = Math.round(fa * 1.4) + 'px';\n      [...ap.querySelectorAll('.check')].forEach(c => c.style.top = Math.round((fa * 1.15 - 66) / 2 + 6) + 'px');\n    };\n    ponerA(); while (ap.offsetHeight > 1500 - apTop && fa > 14) { fa -= 0.5; ponerA(); }\n    // Justificado solo en aprendizajes largos (3+ líneas y más de 90 caracteres, como el diseño); los cortos quedan alineados a la izquierda, sin espacios exagerados)\n    [...ap.querySelectorAll('.item')].forEach(it => { it.style.textAlign = (it.offsetHeight >= Math.round(fa * 1.15) * 3 - 2 && it.textContent.length > 90) ? 'justify' : 'left'; });\n    // Nombres de docentes: letra 25 (3 docentes: más chica); baja si un nombre ocupa más de 3 líneas\n    if (docs.length > 2) $('docentes').classList.add('tres');\n    let fn = docs.length > 2 ? 26 : 34;\n    const noms = [...document.querySelectorAll('#docentes .nombre')];\n    const ponerN = () => noms.forEach(n => { n.style.fontSize = fn + 'px'; n.style.lineHeight = Math.round(fn * 1.25) + 'px'; });\n    ponerN(); ajustarNombres();\n    // Nombres en 2 líneas (títulos / nombre); si no caben, la letra baja (mín. 20)\n    while (noms.some(n => n.offsetHeight > Math.round(fn * 1.25) * 2 + 1) && fn > 20) { fn -= 1; ponerN(); }\n  };\n\n  Promise.all([document.fonts.ready, recortar(d.fotos)]).then(([, fotos]) => {\n    if (fotos) $('fotos').src = fotos;\n    ajustar();\n  });\n</script>\n</body>\n</html>\n", "w": 1080, "h": 1920}};

const d = $('Extraer etiquetas').first().json;
const m = $('Datos de Monday').first().json;
const clave = m.tipo === 'curso' ? 'curso_' + m.linea : m.tipo;   // los cursos se separan por línea: curso_CS / curso_CA
const p = PLANTILLAS[clave];
if (!p) throw new Error('Versión 2 aún no disponible para: ' + clave);

// Fotos de docentes (una por ítem de entrada, ya achicadas a 1000 px) → base64
// Fotos de docentes en base64: las guarda "Prompt aprendizajes" (Gemini no deja pasar las imágenes)
const fotos = (() => { try { return $('Prompt aprendizajes').first().json.fotos || []; } catch (e) { return []; } })();

// "¿Qué aprenderás?" — los redacta Gemini ("Gemini aprendizajes") con los prompts y límites del PDF de variables V2.
// Se acepta hasta un 10 % sobre el límite (la plantilla achica la letra). Si Gemini falla o se pasa más,
// el bloque sale VACÍO y queda un aviso en Monday para que diseño lo complete a mano (nunca texto recortado).
const LIMITES = { seminario: [295, 2], curso_CS: [306, 2], curso_CA: [247, 1], diplomado: [402, 2], acreditacion: [277, 3], especializacion: [301, 2], sesion: [354, 3] };
const [maxCar, maxAp] = LIMITES[m.tipo === 'curso' ? 'curso_' + m.linea : m.tipo] || [295, 2];
const textoGemini = (() => {
  const g = $input.first().json || {};
  const textos = [];
  const buscar = o => { if (!o || typeof o !== 'object') return; for (const [k, v] of Object.entries(o)) { if (k === 'text' && typeof v === 'string') textos.push(v); else if (typeof v === 'object') buscar(v); } };
  buscar(g);
  if (!textos.length && typeof g.content === 'string') textos.push(g.content);
  if (!textos.length && g.aprendizajes) return JSON.stringify(g);
  return textos.join('\n');
})();
let aprendizajes = [], aviso_ia = '';
try {
  const limpio = textoGemini.replace(/```(?:json)?/gi, '').trim();
  const obj = JSON.parse(limpio.slice(limpio.indexOf('{'), limpio.lastIndexOf('}') + 1));
  aprendizajes = (obj.aprendizajes || []).map(x => String(x || '').replace(/^APRENDIZAJE_\d+:\s*/i, '').trim()).filter(Boolean);
} catch (e) { aprendizajes = []; }
const total = aprendizajes.join('').length;
if (!aprendizajes.length) aviso_ia = 'la IA no entregó los aprendizajes';
else if (aprendizajes.length > maxAp) aviso_ia = `la IA entregó ${aprendizajes.length} aprendizajes (máx. ${maxAp})`;
else if (total > Math.floor(maxCar * 1.1)) aviso_ia = `la IA no respetó el límite (${total} de ${maxCar} caracteres)`;
if (aviso_ia) aprendizajes = [];

// Seminario: países de Monday → sigla, zona horaria y bandera (rectangular, flagcdn.com, como Sesión Magistral); hora del Documento Maestro → hora local de cada país
const PAISES = {
  chile:     { cod: 'CL', sigla: 'CHI', zona: 'America/Santiago',               bandera: 'https://flagcdn.com/w160/cl.png' },
  colombia:  { cod: 'CO', sigla: 'COL', zona: 'America/Bogota',                 bandera: 'https://flagcdn.com/w160/co.png' },
  mexico:    { cod: 'MX', sigla: 'MEX', zona: 'America/Mexico_City',            bandera: 'https://flagcdn.com/w160/mx.png' },
  argentina: { cod: 'AR', sigla: 'ARG', zona: 'America/Argentina/Buenos_Aires', bandera: 'https://flagcdn.com/w160/ar.png' },
};
const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
let paises = [];
if (m.tipo === 'seminario') {
  const lp = (m.paises || []).map(x => PAISES[norm(x)]).filter(Boolean);
  const base = Object.values(PAISES).find(x => x.cod === m.pais_doc) || (lp.length === 1 ? lp[0] : null);
  if (!base) throw new Error('No se pudo saber de qué país es la hora del Documento Maestro (falta prefijo CL/MX/CO/AR en el nombre del doc)');
  const desfase = (zona, t) => {
    const q = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: zona, hourCycle: 'h23',
      year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
      .formatToParts(new Date(t)).map(x => [x.type, x.value]));
    return Date.UTC(+q.year, +q.month - 1, +q.day, +q.hour % 24, +q.minute) - t;
  };
  const [Y, M, D] = d.fecha.split('-').map(Number);
  const [h, mi] = d.horario.trim().split(':').map(Number);
  const local = Date.UTC(Y, M - 1, D, h, mi);
  let t = local - desfase(base.zona, local); t = local - desfase(base.zona, t);
  const horaEn = zona => new Intl.DateTimeFormat('en-GB', { timeZone: zona, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(t));
  paises = lp.map(x => ({ sigla: x.sigla, hora: horaEn(x.zona), bandera: x.bandera }));
}

// Cursos: Escuela(s) de la columna "Escuela" del programa → logo (mismos logos de la versión 1)
const CODIGOS = { 'salud mental adultos': 'SMA', 'salud mental infantojuvenil': 'SMIJ', 'psicologia organizacional': 'PO', 'psicosocial juridica': 'PSJ', 'educacion y neurodesarrollo': 'EN' };
const escuelas = m.tipo === 'curso'
  ? (($('Elegir foto SF').first().json.escuelas) || []).map(e => CODIGOS[Object.keys(CODIGOS).find(k => norm(e).includes(k))]).filter(Boolean).slice(0, 2).map(c => R['logo_' + c])
  : [];

const datos = {
  nombre_programa: d.nombre_programa,
  fecha: d.fecha,
  fecha_inicio: d.fecha_inicio,
  paises,
  escuelas,
  docentes: (d.docentes || []).slice(0, 2).map((nombre, i) => ({ nombre, foto: fotos[i] || '' })),
  // Diplomado y Especialización: un solo docente, el director(a) del programa ([director] del Documento Maestro). Acreditación: [docente_1]
  ...(['diplomado', 'especializacion', 'acreditacion'].includes(m.tipo) ? { docente: { nombre: ((($('Elegir foto SF').first().json.fotos) || [])[0] || {}).nombre || (d.docentes || [])[0] || '', foto: fotos[0] || '' }, pronombre: ((($('Elegir foto SF').first().json.fotos) || [])[0] || {}).pronombre || '' } : {}),
  aprendizajes,
  logo_adipa: R.logo_adipa,
  // Sesión Magistral: docentes con bandera (máx. 3), fotos = 1200X1200-POPUP y logo psychotherapy.net
  ...(m.tipo === 'sesion' ? {
    docentes: (($('Elegir foto SF').first().json.docentes_sm) || []).slice(0, 3).map(x => ({ nombre: x.nombre, bandera: x.bandera })),
    fotos: $('POPUP a base64').first().json.popup,
    logo_psy: R.logo_psy,
  } : {}),
};
const json = o => JSON.stringify(o).replace(/</g, '\\u003c');

// Un ítem por pieza: cuadrada + historia (los nodos siguientes se ejecutan una vez por pieza)
const ph = PLANTILLAS_H[clave];
// Aviso para Monday (columna Error, junto al estatus "Revisión de piezas")
const aviso = aviso_ia ? `Aviso V2: "¿Qué aprenderás?" salió vacío porque ${aviso_ia}. Completar a mano` : '';
return [
  { json: { aviso, html: p.html.replace('__DATOS__', () => json(datos)), ancho: p.w, alto: p.h, nombre_base: '1200X1200-RRSS-V2', formatos: ['png'] }, pairedItem: { item: 0 } },
  ...(ph ? [{ json: { aviso, html: ph.html.replace('__DATOS__', () => json(datos)), ancho: ph.w, alto: ph.h, nombre_base: '1080X1920-RRSS-V2', formatos: ['png'] }, pairedItem: { item: 0 } }] : []),
];

// Versión 2 · "¿Qué aprenderás?": arma el prompt para Gemini según la línea (prompts del PDF "EJEMPLO VISUAL VARIABLES V2")
// y guarda las fotos de los docentes en base64 (Gemini no deja pasar las imágenes). Sale 1 solo ítem.
const m = $('Datos de Monday').first().json;
const d = $('Extraer etiquetas').first().json;
const clave = m.tipo === 'curso' ? 'curso_' + m.linea : m.tipo;

// Fotos de docentes (vienen de "Achicar foto docente"; en Sesión Magistral no se usan: van en el POPUP)
const fotos = [];
if (m.tipo !== 'sesion') {
  for (let i = 0; i < $input.all().length; i++) {
    const it = $input.all()[i];
    if (!it.binary || !it.binary.data) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    fotos.push(`data:${it.binary.data.mimeType || 'image/png'};base64,${buf.toString('base64')}`);
  }
}

// Límite de caracteres y cantidad de aprendizajes por línea (PDF de variables V2)
const P = {
  seminario:       { max: 295, n: 2, nombre: 'SEMINARIOS',            verbos: 'comprender, identificar, integrar, aplicar, reconocer, analizar', evita: 'En este seminario aprenderás a…' },
  curso_CS:        { max: 306, n: 2, nombre: 'CURSOS SINCRÓNICOS',    verbos: 'reconocer, comprender, aplicar, identificar, evaluar, integrar', evita: 'En este curso aprenderás…' },
  curso_CA:        { max: 247, n: 1, nombre: 'CURSOS ASINCRÓNICOS',   verbos: 'Aplicar, Comprender, Analizar, Identificar, Desarrollar', evita: 'El objetivo de este curso es…' },
  diplomado:       { max: 402, n: 2, nombre: 'DIPLOMADOS',            verbos: 'analizar, comprender, integrar, aplicar, evaluar, diseñar, identificar', evita: 'En este diplomado aprenderás a…' },
  acreditacion:    { max: 277, n: 3, nombre: 'ACREDITACIONES',        verbos: 'reconocer, analizar, aplicar, administrar, evaluar, desarrollar', evita: 'En esta acreditación aprenderás…' },
  especializacion: { max: 301, n: 2, nombre: 'ESPECIALIZACIONES',     verbos: 'analizar, examinar, aplicar, identificar, integrar, evaluar', evita: 'En esta especialización aprenderás…' },
  sesion:          { max: 354, n: 3, nombre: 'SESIONES MAGISTRALES',  verbos: 'identificar, aplicar, analizar, comprender, evaluar, integrar', evita: 'En esta sesión magistral aprenderás…' },
}[clave] || { max: 295, n: 2, nombre: 'PROGRAMAS', verbos: 'comprender, identificar, aplicar, analizar', evita: 'En este programa aprenderás…' };

const esCA = clave === 'curso_CA';
const etiqueta = esCA ? '[objetivo_general]' : '[objetivos_especificos]';
const fuente = String((esCA ? d.objetivo_general : d.objetivos_especificos) || '').trim();
const objetivo = Math.floor(P.max * 0.9);   // se apunta a un 10 % menos para no pasarse

const prompt = `SECCIÓN: ¿QUÉ APRENDERÁS? — ${P.nombre}
Fuente obligatoria: ${etiqueta} del Documento Maestro (abajo).
Reglas:
- ${esCA ? 'Resume el objetivo general' : 'Resume los objetivos específicos'} en máximo ${objetivo} caracteres totales, incluyendo espacios y signos de puntuación.
- ${P.n === 1 ? 'Redacta 1 solo bloque de aprendizaje.' : `Divide el contenido en máximo ${P.n} aprendizajes.`}
- ${P.n === 1 ? 'Prioriza la capacidad o aplicación principal que adquirirá el estudiante.' : 'Cada aprendizaje debe expresar una idea distinta y relevante.'}
- Conserva el significado original del Documento Maestro.
- No inventes beneficios, conceptos, resultados o promesas que no estén explícitamente respaldados por la fuente.
- ${P.n === 1 ? 'Comienza con un verbo de acción como' : 'Prioriza verbos de acción como'}: ${P.verbos}.
- Evita frases introductorias como "${P.evita}".
- Evita repetir información o conceptos${P.n > 1 ? ' entre los aprendizajes' : ''}.
- Mantén lenguaje profesional, claro y directo, en español neutro.
- Si el texto supera los ${objetivo} caracteres, vuelve a resumir hasta cumplir el límite. Antes de entregar, cuenta los caracteres y valida que el total sea ≤ ${objetivo}.
Formato de salida: responde SOLO con un JSON válido, sin texto adicional ni bloques de código, con esta forma:
{"aprendizajes": [${Array.from({ length: P.n }, (_, i) => `"APRENDIZAJE_${i + 1}"`).join(', ')}], "total_caracteres": 0}

${etiqueta}:
${fuente}`;

return [{ json: { prompt, clave, max: P.max, n: P.n, tiene_fuente: !!fuente, fotos } }];
